"use client";

import { forwardRef, useImperativeHandle, useRef, type SVGProps } from "react";
import {
  motion,
  useAnimate,
  useMotionValue,
  useMotionValueEvent,
  useTransform,
  type AnimationSequence,
  type MotionValue,
  type Transition,
} from "motion/react";
import {
  deriveStops,
  deriveDistanceStops,
  deriveArcEasedStops,
  type CombineEase,
} from "./easing";
import { makeScrubber } from "./scrub";
import type { IconHandle } from "./types";

/* ─────────────────────────────────────────────────────────
 * ANIMATION STORYBOARD — book page flip (snappy tween timing)
 *
 *    0ms   page rests flat on the right stack        (frame 1)
 *  ~140ms  page peels up, gathering speed            (frames 2-3)
 *  ~200ms  page snaps over the spine — fastest beat  (frames 3-4)
 *  ~300ms  page brakes, floats down left             (frames 4-5)
 *   400ms  page lands flat on the left stack         (frame 6)
 *   400ms  hand-off: page melts into the left stack…
 *   520ms  …and the next page surfaces on the right  (frame 1)
 *   640ms  at rest, identical to the start — replays cleanly
 *
 * Unlike the other icons, the flip is NOT a keyframe sequence:
 * per-segment easing pulses at every frame boundary. Instead one
 * progress value runs 0→1 under a single bezier and useTransform
 * maps it onto the six frames at their rotation fractions, so
 * velocity is continuous across the whole turn.
 *
 * Two profiles share this timeline: BookFlipIcon runs a quick quart-bezier
 * tween over hand-authored stops; BookFlipSlowIcon runs dead linear —
 * progress runs linearly AND the frame stops are evenly spaced (derived from
 * a "linear" combine curve, see easing.ts), so every frame-to-frame segment
 * takes the same amount of time: constant speed, no per-segment easing. The
 * leaf also dims at the crest (CREST_SHADE) so the moving page reads as
 * distant while it is edge-on.
 *
 * Generated from 6 frames by scripts/parse-frames.mjs.
 * Path states are validated (identical command structure) — do not
 * hand-edit the d strings; re-export frames and re-run the parser.
 *
 * Paper fill defaults to white; retheme via --icon-paper if the icon
 * sits on a non-white surface.
 * ───────────────────────────────────────────────────────── */

// --ease-in-out-quart from the motion-craft library: steep middle
// (fast crest over the spine), long soft landing.
const FLIP_EASE = [0.77, 0, 0.175, 1] as const;

interface FlipProfile {
  flip: Transition; // drives the page turn (progress 0 → 1)
  melt: number; // page fades into the left stack (seconds)
  surface: number; // next page fades in on the right (seconds)
  // Combine easing: ONE global curve for the whole run. Frame stops are
  // derived from it (each frame lands where the curve reaches its equal
  // value step) instead of the hand-authored FLIP_STOPS. The easing lives
  // entirely in the stop positions, so `flip.ease` must stay linear.
  combineEase?: CombineEase;
  // Arc-length stops: place each frame at its cumulative shape distance so a
  // linear progress morphs at constant *visual* speed — no dwelling on frames
  // whose neighbours barely differ. Wins over combineEase; keep flip.ease linear.
  arcLength?: boolean;
  // Arc-length base RE-TIMED by this curve: constant visual speed (arcLength's
  // benefit) THEN warped in time so the page peels slowly, whips over the
  // spine, and floats down. Highest precedence of the four; keep flip.ease
  // linear (all pacing lives in the stops).
  arcEase?: CombineEase;
}

// Library 1: a quick, tween-driven snap.
const FAST_PROFILE: FlipProfile = {
  flip: { duration: 0.4, ease: [...FLIP_EASE] },
  melt: 0.1,
  surface: 0.12,
};

// Library 2: a truly continuous page turn. Progress runs 0 → 1 linearly and
// the frame stops are placed by ARC LENGTH (deriveDistanceStops) — each of the
// 6 frames sits at its cumulative shape distance, so every segment gets time in
// proportion to how much the shape actually changes. The near-identical poses
// as the page stands up / lays down no longer dwell, and the big cross-spine
// sweep no longer rushes: the page edge travels at constant visual speed, so
// nothing "stops on the points". flip.ease stays linear (the pacing lives
// entirely in the stops).
const LINEAR_PROFILE: FlipProfile = {
  flip: { duration: 0.45, ease: "linear" },
  melt: 0.1,
  surface: 0.12,
  arcLength: true,
};

// Library 3 / hero: the arc-length base (constant visual speed) re-timed by a
// page-flip curve. The physical read of a page turn — a deliberate peel, a fast
// whip across the spine, a long soft landing — that the dead-linear profile
// can't give. Because the base is arc-length, the whip doesn't blow past the
// crest into invisibility (that beat already owns enough distance-space) and
// the near-identical peel/settle poses don't dwell; the ease only redistributes
// TIME. flip.ease stays linear.
//
// The curve is the single dial, and it is TOUCHY: the arc-length base already
// packs 59% of the shape distance into the spine-cross beat, so any ease-in-out
// on top multiplies the contrast. Measured whip ratios (crest edge speed ÷ peel
// edge speed) over these frames:
//   linear            1.0   (the flat "no character" we're replacing)
//   in-out-cubic      5.0   ← here: clear accel/decel, no snap
//   in-out-quart      8.6
//   in-out-quint     12.9   (page crawls then cracks over — too much)
// So the mildest real ease-in-out is already plenty of character on this base.
// Nudge toward quart for more whip; do NOT reach for quint here.
const FLIP_ARC_EASE = [0.645, 0.045, 0.355, 1] as const;

const EASED_PROFILE: FlipProfile = {
  flip: { duration: 0.5, ease: "linear" },
  melt: 0.1,
  surface: 0.12,
  arcEase: FLIP_ARC_EASE,
};

// Depth cue: the leaf dims as it lifts and turns edge-on (min brightness at
// the crest, progress 0.5) and returns to full paper as it lands flat, so the
// moving page reads as farther from the viewer. 1 = full paper brightness.
const CREST_SHADE = 0.82;

// How far through the 180° turn each frame sits (rotation fraction).
// The 3→4 gap is deliberately narrow: combined with the quart bezier's
// peak velocity at progress 0.5, the crest passes in ~20ms.
// Only used when a profile has no combineEase — profiles with one derive
// their stops from the global curve instead (see deriveStops).
const FLIP_STOPS = [0, 0.22, 0.42, 0.58, 0.78, 1];

const PAGE_STATES = [
  "M18.75 3.751C14.25 3.181 10.75 6.251 10.75 6.251L10.75 20.751C10.75 20.751 13.25 17.751 19.75 18.251 20.299 18.19 20.75 17.75 20.75 17.198L20.744 5.626C20.744 4.798 20.069 3.918 18.75 3.751Z",
  "M17.256 1.764C12.579 2.58 10.75 6.251 10.75 6.251L10.75 20.751C10.75 20.751 12.637 16.873 17.75 16.304 18.299 16.243 18.75 15.803 18.75 15.251L18.75 3.139C18.75 2.311 18.072 1.622 17.256 1.764Z",
  "M16.256 0.77C11.579 1.586 10.75 6.252 10.75 6.252L10.75 20.752C10.75 20.752 11.637 15.879 16.75 15.31 17.299 15.249 17.75 14.809 17.75 14.257L17.75 2.145C17.75 1.317 17.072 0.628 16.256 0.77Z",
  "M5.245 0.77C9.921 1.586 10.75 6.252 10.75 6.252L10.75 20.752C10.75 20.752 9.863 15.879 4.75 15.31 4.201 15.249 3.75 14.809 3.75 14.257L3.75 2.145C3.75 1.317 4.428 0.628 5.245 0.77Z",
  "M4.25 1.751C8.927 2.567 10.75 6.251 10.75 6.251L10.75 20.751C10.75 20.751 8.869 16.86 3.755 16.291 3.206 16.23 2.756 15.79 2.756 15.239L2.756 3.126C2.756 2.298 3.434 1.609 4.25 1.751Z",
  "M2.75 3.752C7.25 3.181 10.75 6.252 10.75 6.252L10.75 20.752C10.75 20.752 8.25 17.752 1.75 18.252 1.201 18.191 0.75 17.75 0.75 17.199L0.755 5.626C0.755 4.798 1.431 3.919 2.75 3.752Z",
];

const PAGE = ".book-flip-page";

/**
 * The full timeline as ONE sequence (flip + hand-off), so playAnimation and
 * the Scrub Lab share the exact same animation. The flip drives the
 * `progress` motion value (sequences support motion-value segments); the
 * hand-off is the clone/recolor trick, adapted: flat-left overlays the
 * left cover, so fading there is near-invisible, and the reset to
 * flat-right happens while fully transparent.
 */
function buildSequence(
  progress: MotionValue<number>,
  profile: FlipProfile,
): AnimationSequence {
  return [
    [progress, [0, 1], profile.flip],
    [PAGE, { opacity: [1, 0] }, { duration: profile.melt, ease: "easeOut" }],
    // The page is invisible here; snap it back to flat-right through the
    // progress value, NOT a d write. Sequences merge same-target segments
    // into one keyframe animation, so this stays scrub-safe - a separate
    // paused d animation would pin d to its fill value at every scrubbed
    // time before it starts, stomping the progress-driven pose.
    [progress, [1, 0], { duration: 0.001 }],
    [PAGE, { opacity: [0, 1] }, { duration: profile.surface, ease: "easeOut" }],
  ];
}

const PAPER = "var(--icon-paper, white)";

function createBookFlipIcon(profile: FlipProfile, displayName: string) {
  // Arc-length profiles place each frame at its cumulative shape distance
  // (constant visual speed); combined profiles place each frame where the
  // global curve reaches its equal value step; others keep the hand-authored
  // stops. Resolved once — the profile is fixed for the component's lifetime.
  const stops = profile.arcEase
    ? deriveArcEasedStops(PAGE_STATES, profile.arcEase)
    : profile.arcLength
      ? deriveDistanceStops(PAGE_STATES)
      : profile.combineEase
        ? deriveStops(profile.combineEase, PAGE_STATES.length - 1)
        : FLIP_STOPS;

  const Component = forwardRef<IconHandle, SVGProps<SVGSVGElement>>(
    (props, ref) => {
      const [scope, animate] = useAnimate();
      const pageRef = useRef<SVGPathElement>(null);

      const progress = useMotionValue(0);
      const pageD = useTransform(progress, stops, PAGE_STATES);
      useMotionValueEvent(pageD, "change", (v) => {
        pageRef.current?.setAttribute("d", v);
      });

      // Brightness dips at the crest and returns to full paper at both ends.
      // Derived purely from progress, so it tracks playback and scrubbing
      // without adding a segment to the sequence.
      const pageShade = useTransform(
        progress,
        [0, 0.5, 1],
        [1, CREST_SHADE, 1],
      );
      const pageFilter = useTransform(pageShade, (b) => `brightness(${b})`);

      useImperativeHandle(ref, () => ({
        async playAnimation() {
          progress.jump(0);
          await animate(buildSequence(progress, profile));
        },
        createScrubber() {
          progress.jump(0);
          return makeScrubber(
            () => animate(buildSequence(progress, profile)),
            // The sequence's cancel() restores DOM attributes, but the motion
            // value keeps its last scrubbed value; reset it so the page's d
            // recomputes back to the rest pose.
            () => progress.jump(0),
          );
        },
      }));

      return (
        <svg
          xmlns="http://www.w3.org/2000/svg"
          viewBox="0 0 22 22"
          fill="none"
          style={{ overflow: "visible" }}
          ref={scope}
          {...props}
        >
          <path
            d="M4.083 3.752C6.544 3.748 8.918 4.638 10.75 6.252L10.75 20.751C8.918 19.139 6.544 18.248 4.083 18.251 2.521 18.251 1.74 18.251 1.395 18.031 1.188 17.898 1.103 17.813 0.971 17.606 0.75 17.261 0.75 16.645 0.75 15.414L0.75 7.155C0.75 5.727 0.75 5.013 1.299 4.434 1.847 3.856 2.409 3.826 3.533 3.766 3.715 3.756 3.899 3.752 4.083 3.752Z"
            fill={PAPER}
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
          <path
            d="M17.417 3.752C14.956 3.748 12.582 4.638 10.75 6.252L10.75 20.751C12.582 19.139 14.956 18.248 17.417 18.251 18.979 18.251 19.76 18.251 20.105 18.031 20.312 17.898 20.396 17.813 20.529 17.606 20.75 17.261 20.75 16.645 20.75 15.414L20.75 7.155C20.75 5.727 20.75 5.013 20.201 4.434 19.652 3.856 19.091 3.826 17.967 3.766 17.785 3.756 17.601 3.752 17.417 3.752Z"
            fill={PAPER}
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
          <motion.path
            ref={pageRef}
            className="book-flip-page"
            d={PAGE_STATES[0]}
            fill={PAPER}
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{ filter: pageFilter }}
          />
        </svg>
      );
    },
  );
  Component.displayName = displayName;
  return Component;
}

export const BookFlipIcon = createBookFlipIcon(FAST_PROFILE, "BookFlipIcon");

/** A steady, linear page turn — constant speed through the whole flip. */
export const BookFlipSlowIcon = createBookFlipIcon(
  LINEAR_PROFILE,
  "BookFlipSlowIcon",
);

/**
 * Constant visual speed re-timed by a page-flip curve: deliberate peel, fast
 * whip over the spine, soft float-down. The characterful default for showcase
 * surfaces where the flip is the whole point.
 */
export const BookFlipEasedIcon = createBookFlipIcon(
  EASED_PROFILE,
  "BookFlipEasedIcon",
);

/**
 * Combine-easing math: express a whole keyframe run as ONE global easing
 * curve, then place each intermediate keyframe at the time where that curve
 * naturally passes through its equal value step. This is the "retime" half
 * of the After Effects-style "Combine" operation.
 *
 * Pure cubic-bezier helpers — P0=(0,0), P3=(1,1), control points (x1,y1),
 * (x2,y2), same parameterization as CSS cubic-bezier() and Motion's array
 * easing.
 */

export type CombineEase = readonly [number, number, number, number] | "linear";

/**
 * The time fraction x at which the easing's value y reaches `v`.
 * Linear returns v unchanged. Bezier: bisection-solve Y(s) = v for the
 * curve parameter s (Y is monotonic for valid easings), then evaluate X(s).
 */
export function easeTimeFracAtValue(ease: CombineEase, v: number): number {
  if (v <= 0) return 0;
  if (v >= 1) return 1;
  if (ease === "linear") return v;
  const [x1, y1, x2, y2] = ease;
  const bez = (s: number, c1: number, c2: number) =>
    3 * (1 - s) ** 2 * s * c1 + 3 * (1 - s) * s * s * c2 + s ** 3;
  let lo = 0;
  let hi = 1;
  for (let i = 0; i < 30; i++) {
    const mid = (lo + hi) / 2;
    if (bez(mid, y1, y2) < v) {
      lo = mid;
    } else {
      hi = mid;
    }
  }
  const x = bez((lo + hi) / 2, x1, x2);
  return Math.min(1, Math.max(0, x));
}

/**
 * Stop positions (input range for useTransform) that make `segCount` equal
 * value steps land on one continuous easing curve: stop[i] is the time
 * fraction where the curve's value reaches i / segCount. Strictly ascending
 * for any monotonic easing.
 */
export function deriveStops(ease: CombineEase, segCount: number): number[] {
  const stops: number[] = [];
  for (let i = 0; i <= segCount; i++) {
    stops.push(easeTimeFracAtValue(ease, i / segCount));
  }
  return stops;
}

/**
 * Arc-length stop positions for a keyframe morph: place each keyframe at its
 * cumulative shape distance so that EQUAL time = EQUAL visual change. Without
 * this, keyframes that are close together in shape-space (a pose that barely
 * differs from its neighbour) dwell on screen while a distant pair rushes —
 * the morph looks like it stops on the frames.
 *
 * All keyframes here share an identical path-command structure, so the numeric
 * coordinates line up 1:1 across the `d` strings; the distance between two
 * frames is just the Euclidean norm of their coordinate differences. Returns a
 * strictly ascending range in [0, 1] to feed useTransform's input, so a
 * linearly-advancing progress value morphs the shape at constant speed.
 */
export function deriveDistanceStops(states: readonly string[]): number[] {
  const nums = states.map((s) =>
    (s.match(/-?\d*\.?\d+(?:e-?\d+)?/gi) ?? []).map(Number),
  );
  const dist: number[] = [];
  for (let i = 1; i < nums.length; i++) {
    let sumSq = 0;
    for (let j = 0; j < nums[i].length; j++) {
      const d = nums[i][j] - nums[i - 1][j];
      sumSq += d * d;
    }
    dist.push(Math.sqrt(sumSq));
  }
  const total = dist.reduce((a, b) => a + b, 0) || 1;
  const stops = [0];
  let acc = 0;
  for (const d of dist) {
    acc += d;
    stops.push(acc / total);
  }
  return stops;
}

/**
 * Arc-length stops RE-TIMED by a temporal easing curve — the "combine" of both
 * pacing tools. deriveDistanceStops gives a constant-visual-speed baseline (no
 * dwelling on near-identical frames, no rushing the big sweep); this then warps
 * that baseline in TIME so motion runs slow → fast → slow, the way a real page
 * peels, whips over the spine, and floats down.
 *
 * A frame sitting at cumulative-distance fraction c should appear at the time
 * where the ease's VALUE reaches c — i.e. easeTimeFracAtValue(ease, c). So the
 * ease acts as the distance-travelled-vs-time profile on top of the
 * distance-normalized layout. A "linear" ease degenerates to plain arc-length
 * stops, so this strictly generalizes deriveDistanceStops. Strictly ascending
 * for any monotonic ease (both inputs are monotonic), endpoints stay 0 and 1.
 */
export function deriveArcEasedStops(
  states: readonly string[],
  ease: CombineEase,
): number[] {
  return deriveDistanceStops(states).map((c) => easeTimeFracAtValue(ease, c));
}

import type { IconScrubber } from "./types";

/**
 * Structural subset of Motion's AnimationPlaybackControls that scrubbing
 * needs; both `animate(sequence)` and `animate(value, ...)` results satisfy
 * it, so icons don't have to care which form their timeline takes.
 */
interface PlaybackControls {
  duration: number;
  time: number;
  pause(): void;
  stop(): void;
}

/**
 * Turn an icon's animation into a paused, seekable scrubber. The animation
 * is created and paused immediately (before the first frame renders), so
 * the icon holds its rest pose until the first seek.
 */
export function makeScrubber(
  createAnimation: () => PlaybackControls,
  onDestroy?: () => void
): IconScrubber {
  const controls = createAnimation();
  controls.pause();
  const duration = controls.duration;

  const nudge = () => {
    controls.time = Math.min(1e-4, duration);
    controls.time = 0;
  };

  // Repair the t=0 pose once Motion has resolved keyframes. A freshly
  // created, immediately paused sequence flushes *unresolved* fill values
  // into the DOM (e.g. the Automations pulse gets a literal
  // opacity="undefined" attribute and renders fully visible instead of
  // hidden). Resolution happens on Motion's frame loop, so wait two frames,
  // then seek away from and back to 0 to force one resolved render.
  // Skipped if the user scrubs first - a real seek renders correctly.
  let pendingInit: number | null = requestAnimationFrame(() => {
    pendingInit = requestAnimationFrame(() => {
      pendingInit = null;
      nudge();
    });
  });
  const cancelInit = () => {
    if (pendingInit !== null) {
      cancelAnimationFrame(pendingInit);
      pendingInit = null;
    }
  };

  return {
    duration,
    seek(seconds: number) {
      cancelInit();
      const t = Math.min(Math.max(seconds, 0), duration);
      // Plain `time = 0` on the never-rendered timeline replays the
      // unresolved-fill bug above; route through the nudge instead.
      if (t === 0) nudge();
      else controls.time = t;
    },
    destroy() {
      cancelInit();
      // stop(), not cancel(): cancel() on an animation that has not rendered
      // a frame yet (React StrictMode's create->destroy->create effect cycle)
      // writes unresolved "undefined" values back into the DOM, corrupting
      // the icon. stop() never writes; callers remount the icon per scrub
      // session, so rest-state restoration comes from React.
      controls.stop();
      onDestroy?.();
    },
  };
}

/**
 * A paused handle onto an icon's full animation timeline, for posing it at
 * an arbitrary moment (the Scrub Lab). Times are in seconds, matching
 * Motion's AnimationPlaybackControls.
 */
export interface IconScrubber {
  /** Total timeline length in seconds. */
  duration: number;
  /** Pose the animation at `seconds` (clamped to [0, duration]). */
  seek(seconds: number): void;
  /** Cancel the paused animation and return the icon to its rest state. */
  destroy(): void;
}

export interface IconHandle {
  playAnimation(): Promise<void>;
  /** Optional: create a paused, seekable instance of the same timeline. */
  createScrubber?(): IconScrubber;
}

"use client";

import { forwardRef, useImperativeHandle, type SVGProps } from "react";
import { motion, useAnimate, type AnimationSequence } from "motion/react";
import { makeScrubber } from "./scrub";
import type { IconHandle } from "./types";

/* ─────────────────────────────────────────────────────────
 * ANIMATION STORYBOARD — rolling cart with speed lines
 *
 *    0ms  at rest: no speed lines visible              (f1)
 *  120ms  bump: basket tips                            (f2)
 *         speed line 1 fades in, streaking backward
 *  280ms  body rises 0.5 on its suspension             (f3)
 *         speed line 2 fades in, streaking backward
 *  430ms  body falls back                              (f4)
 *  750ms  both speed lines have streaked out           (gone)
 *  900ms  body settles to the exact rest pose          (f1)
 *
 * The whole cart also ROLLS horizontally: body + wheels translate together
 * — a small load backward, then a roll forward, then an ease back to rest —
 * so it reads as actually moving, not just tipping in place. It's a slide,
 * NO vertical hop (that read as jumping). The two speed lines behind the cart
 * reinforce the roll: invisible at rest, they only exist during the hover run
 * and end at opacity 0, so the loop seam stays invisible.
 *
 * Generated from 6 frames by scripts/parse-frames.mjs.
 * Path states are validated (identical command structure) - do not
 * hand-edit the d strings; re-export frames and re-run the parser.
 * ───────────────────────────────────────────────────────── */

const PATH_1_STATES = [
  "M0.5 0.5L2.664 0.897C3.013 0.961 3.303 1.205 3.424 1.539L3.773 2.5M6.5 10L15.072 10C15.493 10 15.868 9.737 16.012 9.342L18.012 3.842C18.124 3.535 18.079 3.194 17.891 2.926 17.704 2.659 17.398 2.5 17.072 2.5L3.772 2.5M6.5 10L3.773 2.5M6.5 10L5.877 10.952C5.676 11.259 5.659 11.652 5.834 11.975 6.008 12.298 6.346 12.5 6.713 12.5L15.773 12.5",
  "M0.5 0.5L2.664 0.897C3.013 0.961 3.303 1.205 3.424 1.539L3.773 2.5M6.5 10L15.018 10.627C15.464 10.66 15.878 10.392 16.031 9.971L18.035 4.461C18.144 4.162 18.104 3.829 17.928 3.565 17.751 3.3 17.46 3.135 17.142 3.12L3.772 2.5M6.5 10L3.773 2.5M6.5 10L5.877 10.952C5.676 11.259 5.659 11.652 5.834 11.975 6.008 12.298 6.346 12.5 6.713 12.5L15.773 12.5",
