        <motion.g
          className="focus-frame"
          style={{ transformBox: "view-box", transformOrigin: "center" }}
        >
          <motion.path className="focus-brackets" d={BRACKET_STATES[0]} />
          <motion.circle
            className="focus-flash"
            cx={12}
            cy={12}
            r={7.5}
            fill="currentColor"
            stroke="none"
            opacity={0}
          />
          <motion.path
            className="focus-dot"
            d={DOT_D}
            style={{ transformBox: "fill-box", transformOrigin: "center" }}
          />
        </motion.g>
      </svg>
    );
  }
);

