  /** Total timeline length in seconds. */
  duration: number;
  /** Pose the animation at `seconds` (clamped to [0, duration]). */
  seek(seconds: number): void;
  /** Cancel the paused animation and return the icon to its rest state. */
  destroy(): void;
}

export interface IconHandle {
  playAnimation(): Promise<void>;
  /** Optional: create a paused, seekable instance of the same timeline. */
  createScrubber?(): IconScrubber;
}

"use client";

import { forwardRef, useImperativeHandle, type SVGProps } from "react";
import {
  motion,
  useAnimate,
  useReducedMotion,
  type AnimationSequence,
  type Easing,
} from "motion/react";
import { makeScrubber } from "./scrub";
import type { IconHandle } from "./types";

/* ─────────────────────────────────────────────────────────
 * ANIMATION STORYBOARD — the frame ratchets shut in three
 * notches, locks, then springs open (hover)
 *
 *    0ms  four corner brackets at rest, wide and softly
 *         rounded                                    (r = 4)
 *  115ms  CLICK 1 — the frame snaps inward and the corners
 *         lose most of their roundness             (r = 2.75)
 *  220ms  ...and HOLDS there. The hold is the notch.
 *  335ms  CLICK 2 — inward again, corners squarer   (r = 1.55)
 *  425ms  hold
 *  540ms  CLICK 3 — the last notch, corners now essentially
 *         sharp: a tight square viewfinder           (r = 0.4)
 *  665ms  LOCKED — the longest hold of the three. Stillness
 *         is what makes the release read as a release.
 * 1040ms  RELEASE — ONE continuous 375ms sweep home, easeInOut.
 *         Size and corner radius travel together the whole way:
 *         the frame is still growing while its corners are
 *         still rounding, and nothing is left to finish after
 *         it lands. No overshoot either — it never goes wider
 *         than rest, and ends pixel-identical to frame 0 (§0.2).
 *
 * THREE SNAPS, ONE RELEASE. Each notch is 115ms of quart-out
 * (it cracks) followed by a dead-still hold; the way home is a
 * single 375ms sweep. Mechanical going in, organic coming out —
 * that contrast is the whole gesture. Without the holds this is
 * a stutter; with them it is a ratchet.
 *
 * WHY THE PATH MORPHS INSTEAD OF THE FRAME SCALING. A CSS
 * `scale` would shrink the corner radius in lockstep with the
 * size (the shape would stay the same shape, just smaller) and
 * would thin the 1.5 stroke on the way. Here size and roundness
 * are INDEPENDENT parameters of a generated path, so the corners
 * can square off faster than the frame shrinks — r/h runs
 * 0.50 → 0.39 → 0.24 → 0.07 — and the stroke never changes
 * weight.
 *
 * ONE CLOCK, ONE PART. Everything lives in a single `d`
 * keyframe array — nothing to keep in sync, and every part of
 * the shape (extent, radius, arm gap) is affine in the notch
 * parameters, so Motion's numeric lerp between two states IS
 * the exact parametric in-between, not an approximation of it.
 * ───────────────────────────────────────────────────────── */

/** viewBox centre — the frame closes on this point from all four sides. */
const CENTER = 8.75;
/** Circle constant: control-handle length for a quarter-arc of radius r. */
const KAPPA = 0.5522847498307936;

/** Sign pairs for the four brackets: TL, TR, BR, BL. */
const CORNERS = [
  [-1, -1],
  [1, -1],
  [1, 1],
  [-1, 1],
] as const;

/**
 * One state of the frame:
 *   h   — half-extent, centre to edge (the size)
 *   r   — corner radius (the roundness)
 *   gap — half the opening at each edge midpoint (how far the arms reach)
 */
interface Notch {
  h: number;
  r: number;
  gap: number;
}

/**
 * Build the four corner brackets for one notch, as a single `d` with four
 * subpaths. Each bracket is drawn identically — move to the arm end, run to
 * the corner, one cubic quarter-arc, run back out along the other edge — so
 * every state emits the same command letters and the same 48 numbers. That is
 * the Class C morph contract (§2), guaranteed by construction rather than
 * checked by eye.
 *
 * At the rest notch this reproduces the source glyph coordinate for
 * coordinate (its `V`/`H` shorthand written out as `L`).
 */
function framePath({ h, r, gap }: Notch): string {
  return CORNERS.map(([sx, sy]) => {
    const x = (offset: number) => (CENTER + sx * offset).toFixed(3);
    const y = (offset: number) => (CENTER + sy * offset).toFixed(3);
    // Where the arc's control handles sit: KAPPA of the radius back from the
    // corner, along each edge.
    const bend = h - r * (1 - KAPPA);
    return (
      `M${x(h)} ${y(gap)}` +
      `L${x(h)} ${y(h - r)}` +
      `C${x(h)} ${y(bend)} ${x(bend)} ${y(h)} ${x(h - r)} ${y(h)}` +
      `L${x(gap)} ${y(h)}`
    );
  }).join("");
}

/**
 * The four poses. Size steps in slightly shrinking increments (0.85, 0.80,
 * 0.75) like a ratchet running out of travel, while the radius drops much
 * faster — squaring off is the dominant read. The arms lengthen a little into
 * each notch (gap tightens from 0.25·h to 0.205·h), so the brackets close on
 * the centre as well as shrink.
 */
const REST: Notch = { h: 8.0, r: 4.0, gap: 2.0 };
const NOTCH_1: Notch = { h: 7.15, r: 2.75, gap: 1.702 };
const NOTCH_2: Notch = { h: 6.35, r: 1.55, gap: 1.41 };
const NOTCH_3: Notch = { h: 5.6, r: 0.4, gap: 1.148 };

const REST_D = framePath(REST);

/** rest → click, hold, click, hold, click, LOCK, and straight home. The last
 *  state is REST itself, with no pose in between: that is what keeps size and
 *  radius on one interpolation the whole way back, instead of one finishing
 *  first and the other catching up afterwards. */
const STATES = [
  REST,
  NOTCH_1,
  NOTCH_1,
  NOTCH_2,
  NOTCH_2,
  NOTCH_3,
  NOTCH_3,
  REST,
].map(framePath);

const DURATION = 1.04;
/** Duplicated states are the holds; they shorten (105→90ms) as the ratchet
 *  tightens, then the lock beat runs longest (125ms) before the release. */
const TIMES = [0, 0.111, 0.212, 0.322, 0.409, 0.519, 0.639, 1];
/**
 * Quart-out on every notch: half the travel in the first frame, then four more
 * frames of visible deceleration. It still cracks, but it MOVES — an expo-out
 * this short (or a snappier ease) lands at 71% on frame one, which renders as a
 * hard cut, and three hard cuts in a row read as a glitch rather than a ratchet.
 * Linear across the holds (nothing changes).
 *
 * The release is easeInOut, not a quint-out: a snappy ease would spend most of
 * the 375ms already home, so the roundness would resolve in the first fifth of
 * the sweep and the rest would look static. easeInOut spreads the change across
 * the whole way back, which is what makes the corners read as opening up
 * gradually rather than all at once.
 */
const CLICK: Easing = [0.25, 1, 0.5, 1];
const EASES: Easing[] = [
  CLICK,
  "linear",
  CLICK,
  "linear",
  CLICK,
  "linear",
  "easeInOut",
];

const SEQUENCE: AnimationSequence = [
  [
    ".scan-frame",
    { d: STATES },
    { duration: DURATION, times: TIMES, ease: EASES },
  ],
];

export const ScanIcon = forwardRef<
  IconHandle,
  Omit<SVGProps<SVGSVGElement>, "ref">
>((props, ref) => {
  const [scope, animate] = useAnimate();
  const shouldReduceMotion = useReducedMotion();

  useImperativeHandle(ref, () => ({
    async playAnimation() {
      // Guarded here as well as in the trigger row: the export gallery's
      // preview hover has no reduced-motion check of its own.
      if (shouldReduceMotion) return;
      await animate(SEQUENCE);
    },
    createScrubber() {
      return makeScrubber(() => animate(SEQUENCE));
    },
  }));

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="18"
      height="18"
      viewBox="0 0 18 18"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.5}
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{ overflow: "visible" }}
      ref={scope}
      {...props}
    >
      <motion.path className="scan-frame" d={REST_D} />
    </svg>
  );
});

ScanIcon.displayName = "ScanIcon";

import type { IconScrubber } from "./types";

/**
 * Structural subset of Motion's AnimationPlaybackControls that scrubbing
 * needs; both `animate(sequence)` and `animate(value, ...)` results satisfy
 * it, so icons don't have to care which form their timeline takes.
 */
interface PlaybackControls {
  duration: number;
  time: number;
  pause(): void;
  stop(): void;
}

/**
 * Turn an icon's animation into a paused, seekable scrubber. The animation
 * is created and paused immediately (before the first frame renders), so
 * the icon holds its rest pose until the first seek.
 */
export function makeScrubber(
  createAnimation: () => PlaybackControls,
  onDestroy?: () => void
): IconScrubber {
  const controls = createAnimation();
  controls.pause();
  const duration = controls.duration;

  const nudge = () => {
    controls.time = Math.min(1e-4, duration);
    controls.time = 0;
  };

  // Repair the t=0 pose once Motion has resolved keyframes. A freshly
  // created, immediately paused sequence flushes *unresolved* fill values
  // into the DOM (e.g. the Automations pulse gets a literal
  // opacity="undefined" attribute and renders fully visible instead of
  // hidden). Resolution happens on Motion's frame loop, so wait two frames,
  // then seek away from and back to 0 to force one resolved render.
  // Skipped if the user scrubs first - a real seek renders correctly.
  let pendingInit: number | null = requestAnimationFrame(() => {
    pendingInit = requestAnimationFrame(() => {
      pendingInit = null;
      nudge();
    });
  });
  const cancelInit = () => {
    if (pendingInit !== null) {
      cancelAnimationFrame(pendingInit);
      pendingInit = null;
    }
  };

  return {
    duration,
    seek(seconds: number) {
      cancelInit();
      const t = Math.min(Math.max(seconds, 0), duration);
      // Plain `time = 0` on the never-rendered timeline replays the
      // unresolved-fill bug above; route through the nudge instead.
      if (t === 0) nudge();
      else controls.time = t;
    },
    destroy() {
      cancelInit();
      // stop(), not cancel(): cancel() on an animation that has not rendered
      // a frame yet (React StrictMode's create->destroy->create effect cycle)
      // writes unresolved "undefined" values back into the DOM, corrupting
      // the icon. stop() never writes; callers remount the icon per scrub
      // session, so rest-state restoration comes from React.
      controls.stop();
      onDestroy?.();
    },
  };
}

/**
 * A paused handle onto an icon's full animation timeline, for posing it at
 * an arbitrary moment (the Scrub Lab). Times are in seconds, matching
 * Motion's AnimationPlaybackControls.
 */
export interface IconScrubber {
  /** Total timeline length in seconds. */
  duration: number;
  /** Pose the animation at `seconds` (clamped to [0, duration]). */
  seek(seconds: number): void;
  /** Cancel the paused animation and return the icon to its rest state. */
  destroy(): void;
}

export interface IconHandle {
  playAnimation(): Promise<void>;
  /** Optional: create a paused, seekable instance of the same timeline. */
  createScrubber?(): IconScrubber;
}

"use client";

import { forwardRef, useImperativeHandle, useRef, type SVGProps } from "react";
import {
  useAnimate,
  useMotionValue,
  useMotionValueEvent,
  useReducedMotion,
  useTransform,
  type AnimationSequence,
  type MotionValue,
} from "motion/react";
import { makeScrubber } from "./scrub";
import type { IconHandle } from "./types";

/* ─────────────────────────────────────────────────────────
 * ANIMATION STORYBOARD — the gem turns on its own axis
 * (the facets sweep west→east 360° — two 180° passes — in
 * one ease-in-out-quint gesture: long quiet wind-up, a
 * snappy multi-revolution whip through mid-flight, long
 * braking glide into the landing)
 *
 *    0ms  gem at rest: silhouette, girdle line, facets at
 *         {-90°, -30°, +30°}                       (frame 1)
 *  0-1500ms  facets sweep 360°, never pausing
 *  1500ms  360° is a multiple of the 60° facet spacing, so
 *         the set maps onto itself → pixel-identical to
 *         rest, replays seamlessly
 *
 * GlobeSpinIcon's technique, on a different solid — Class D-3
 * per ICON-SYSTEM §2, built numerically rather than from a
 * d-morph, because facets merge into the silhouette at the
 * limb and a morph cannot change topology.
 *
 * WHY THE GLOBE'S MATH WORKS HERE. The gem is a solid of
 * REVOLUTION about its vertical axis: a top circle (radius
 * R_TOP), a girdle circle (R_GIRDLE) and an apex point. Under
 * an orthographic side view a point at radius ρ and longitude
 * θ projects to x = CX + ρ·sin θ with its y fixed, so a facet
 * line is just three points — top circle, girdle circle, apex
 * (ρ = 0, hence pinned) — and the whole spin is one sine.
 * Two consequences make the icon work:
 *
 *   - the SILHOUETTE is invariant. Spinning a solid of
 *     revolution about its own axis cannot change its outline,
 *     so the outer path and the girdle line are static, exactly
 *     like the globe's limb circle and latitude chords.
 *   - the HAND-OFF is exact. At θ = ±90° a facet's points are
 *     (CX ± R_TOP, Y_TOP) and (CX ± R_GIRDLE, Y_GIRDLE) — the
 *     silhouette's own bevel and lower edge. A facet reaching
 *     the limb coincides with the outline, hides under its
 *     stroke, and re-emerges on the far side. No fade, no
 *     clone: ICON-SYSTEM loop strategy 3, composition hand-off.
 *
 * Facet d strings are recomputed per frame from ONE `spin`
 * motion value (BookFlip/Search3D pattern), so hover playback
 * and the Scrub Lab pose the same pure function of time. The
 * command structure is always M L L, so every scrub seek lands
 * on valid geometry.
 *
 * Drawn from the supplied 44-grid glyph, rebuilt on an 18 grid
 * at strokeWidth 1.5 to match the rest of the set. The authored
 * facets were close to but not exactly a projection (their top
 * points sat ~1 unit wide of where the sine puts them); the
 * geometry here is the consistent version, which is what lets
 * the same function serve every frame of the turn.
 * ───────────────────────────────────────────────────────── */

const DURATION = 1.5;

/** ease-in-out-quint: quieter ends, snappier whip mid-turn than quart. */
const EASE_IN_OUT_QUINT = [0.86, 0, 0.07, 1] as const;

/** Axis of revolution, and the three heights the solid is defined at. */
const CX = 9;
const Y_TOP = 1.5;
const Y_GIRDLE = 6;
const Y_APEX = 16.5;

/** Radius of the top circle (the table) and of the girdle — the widest ring.
 *  Their ratio, 0.48, is the supplied glyph's proportion. */
const R_TOP = 3.6;
const R_GIRDLE = 7.5;

/**
 * Rest longitudes, uniformly 60° apart so any multiple-of-60° advance maps the
 * set onto itself. -90° sits exactly under the left bevel at rest, so the
 * visible rest glyph is the outline + girdle + two facets at ±30° — the
 * supplied frame 1 exactly.
 */
const FACET_LONGITUDES = [-90, -30, 30];
/** Total sweep: two 180° passes, so the gem visibly turns ~2×. */
const SPIN_DEGREES = 360;

const n = (v: number) => Number(v.toFixed(3));

/**
 * The silhouette: table edge, two bevels down to the girdle, two edges down to
 * the apex. Static — see the storyboard's invariance note. Round joins do the
 * corner rounding the authored glyph spelled out as cubics.
 */
const OUTLINE_D =
  `M${n(CX - R_TOP)} ${Y_TOP}` +
  `L${n(CX + R_TOP)} ${Y_TOP}` +
  `L${n(CX + R_GIRDLE)} ${Y_GIRDLE}` +
  `L${CX} ${Y_APEX}` +
  `L${n(CX - R_GIRDLE)} ${Y_GIRDLE}Z`;

/** The girdle, seen edge-on: a chord across the widest ring. */
const GIRDLE_D = `M${n(CX - R_GIRDLE)} ${Y_GIRDLE}H${n(CX + R_GIRDLE)}`;

/** Keep longitude in [-90°, 90°): the front-facing half. A facet on the back
 *  projects onto the same x as its front counterpart, so the two are one line. */
function wrapLongitude(deg: number): number {
  return ((((deg + 90) % 180) + 180) % 180) - 90;
}

/**
 * One facet at `longitude`: table point, girdle point, apex. Both moving
 * points ride the same sine, scaled by their own ring's radius — which is what
 * makes the facet foreshorten toward the edges instead of sliding rigidly.
 * Always M L L, so the command structure never changes.
 */
function facetD(longitude: number): string {
  const s = Math.sin((longitude * Math.PI) / 180);
  return (
    `M${n(CX + R_TOP * s)} ${Y_TOP}` +
    `L${n(CX + R_GIRDLE * s)} ${Y_GIRDLE}` +
    `L${CX} ${Y_APEX}`
  );
}

function buildSequence(spin: MotionValue<number>): AnimationSequence {
  return [[spin, [0, 1], { duration: DURATION, ease: [...EASE_IN_OUT_QUINT] }]];
}

export const GemIcon = forwardRef<
  IconHandle,
  Omit<SVGProps<SVGSVGElement>, "ref">
>((props, ref) => {
  const [scope, animate] = useAnimate();
  const spin = useMotionValue(0);
  const shouldReduceMotion = useReducedMotion();
  const facetRefs = useRef<(SVGPathElement | null)[]>([]);

  const facetDs = useTransform(spin, (p) =>
    FACET_LONGITUDES.map((lon) =>
      facetD(wrapLongitude(lon + SPIN_DEGREES * p)),
    ),
  );
  useMotionValueEvent(facetDs, "change", (ds) => {
    ds.forEach((d, i) => facetRefs.current[i]?.setAttribute("d", d));
  });

  useImperativeHandle(ref, () => ({
    async playAnimation() {
      // Guarded here as well as in the trigger row: the export gallery's
      // preview hover has no reduced-motion check of its own.
      if (shouldReduceMotion) return;
      spin.jump(0);
      await animate(buildSequence(spin));
    },
    createScrubber() {
      spin.jump(0);
      return makeScrubber(
        () => animate(buildSequence(spin)),
        // Sequence cancel restores DOM attributes, but the motion value keeps
        // its last scrubbed value; reset so facets recompute back to rest.
        () => spin.jump(0),
      );
    },
  }));

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="18"
      height="18"
      viewBox="0 0 18 18"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.5}
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{ overflow: "visible" }}
      ref={scope}
      {...props}
    >
      <path d={OUTLINE_D} />
      <path d={GIRDLE_D} />
      {/* Facets: d is driven imperatively from the spin motion value. */}
      {FACET_LONGITUDES.map((lon, i) => (
        <path
          key={lon}
          ref={(el) => {
            facetRefs.current[i] = el;
          }}
          d={facetD(lon)}
        />
      ))}
    </svg>
  );
});

GemIcon.displayName = "GemIcon";

