"use client";

import { forwardRef, useImperativeHandle, useRef, type SVGProps } from "react";
import {
  useAnimate,
  useMotionValue,
  useMotionValueEvent,
  useReducedMotion,
  useTransform,
  type AnimationSequence,
  type Easing,
  type MotionValue,
} from "motion/react";
import { makeScrubber } from "./scrub";
import type { IconHandle } from "./types";

/* ─────────────────────────────────────────────────────────
 * ANIMATION STORYBOARD — the two sparkles trade size, twice
 * (hover)
 *
 *    0ms  big sparkle bottom-left, small one top-right
 *         TRADE — they exchange on a spring: the big one
 *         shrinks to the small size while the small one grows
 *         to the big size. The spring overshoots, so at the
 *         peak the shrinking star goes a little SMALLER than
 *         its target and the growing one a little BIGGER,
 *         then both ring back.
 *         TRADE BACK — the same spring the other way:
 *         big → small → big, once.
 *  ~830ms settled, pixel-identical to rest (§0.2) — the back
 *         half IS the way home, so however many cycles run,
 *         the gesture ends on the rest pose.
 *
 * Measured in headless Chrome, not estimated: 2 crossings of
 * the halfway size and a final radius of exactly 4.80 (rest),
 * on both a mouse hover and a touch tap.
 *
 * SHARPNESS RIDES SIZE. Each star is parametric in two axes:
 * `r` (arm reach) and `pull` (where the flank curves' control
 * points sit, as a fraction of r — 1.0 puts them on the arm
 * tips for a blunt diamond, near 0 pulls them to the centre so
 * the flanks collapse and the arms become needles). pull is
 * interpolated alongside r, so whichever star is currently
 * big is also the sharper one. That is optical, not decorative:
 * stroke width is constant, so a small star drawn at the big
 * one's 0.30 waist would close its inner hole into a blob.
 * Matching them numerically would mismatch them optically.
 *
 * WHY THE STARS SIT ON A DIAGONAL, WELL APART. A full size
 * swap means BOTH seats have to be able to host the big star,
 * which rules out nesting the small one in the big one's
 * notch — mid-swap the two are near-equal and their arms
 * collide. Seats mirrored about the anti-diagonal give 1.6
 * units of clearance at the worst moment (both at r≈3.6) and
 * make the exchange read as a true swap, because the two
 * compositions are mirror images of each other.
 *
 * An earlier pass also spun each star 90° per swap — free in
 * principle, since a 4-fold-symmetric star maps onto itself
 * every 90°. It is not free here: at the halfway point that
 * puts every arm at 45°, pointing straight down the diagonal
 * at its neighbour, and the arms overlap. Size alone carries
 * the gesture.
 *
 * TWO CHOREOGRAPHIES (the GithubIcon / PlayIcon split):
 *   playAnimation()  → real springs — the hover feel
 *   createScrubber() → a keyframed twin, because makeScrubber
 *                      seeks by time and a spring's duration
 *                      is derived. Kept in sync by hand.
 *
 * SPRINGS GO IN DISCRETE animate() CALLS, NEVER IN AN
 * AnimationSequence. Written first as a two-segment sequence
 * with the second overlapped onto the first (`at: "-0.18"`),
 * this icon rendered ONE frame and never moved — verified in
 * headless Chrome, 93 samples, 1 distinct `d`. A sequence
 * pre-resolves a timeline, so a spring (whose duration is
 * derived, not declared) and two overlapping writes to the
 * same MotionValue have nothing coherent to resolve to. Every
 * other spring icon here — GithubIcon, PlayIcon, HomeDoorIcon
 * — awaits separate animate() calls and uses `delay` for the
 * beat between them. Sequences are for tweens (GlobeSpinIcon,
 * GemIcon), which do declare a duration.
 * ───────────────────────────────────────────────────────── */

/** Arm directions, in draw order: up, right, down, left. */
const ARMS = [
  [0, -1],
  [1, 0],
  [0, 1],
  [-1, 0],
] as const;

const n = (v: number) => Number(v.toFixed(3));
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

/**
 * A four-pointed sparkle. Each flank is one cubic from arm tip to arm tip
 * whose control points are those same tips pulled toward the centre by
 * `pull` — so the curve leaves each tip along its own axis and the tip stays
 * a true point at any sharpness. Always M C C C C Z, so every scrub seek
 * lands on valid geometry.
 */
function starD(cx: number, cy: number, r: number, pull: number): string {
  const at = (arm: readonly [number, number] | number[], k: number) =>
    `${n(cx + arm[0] * r * k)} ${n(cy + arm[1] * r * k)}`;
  let d = `M${at(ARMS[0], 1)}`;
  for (let i = 0; i < 4; i++) {
    const j = (i + 1) % 4;
    d += `C${at(ARMS[i], pull)} ${at(ARMS[j], pull)} ${at(ARMS[j], 1)}`;
  }
  return `${d}Z`;
}

/** The two seats, mirrored about the anti-diagonal. Each is far enough from
 *  its edges to host the BIG star, which is what makes a full swap possible. */
const SEAT_A = { cx: 6.1, cy: 11.9 } as const;
const SEAT_B = { cx: 11.9, cy: 6.1 } as const;

/** The two sizes being traded, and the waist that goes with each. */
const R_BIG = 4.8;
const R_SMALL = 2.4;
const PULL_BIG = 0.3;
const PULL_SMALL = 0.42;

/** swap = 0 → A is the big one; swap = 1 → B is. Spring overshoot pushes
 *  past both ends, which is exactly the pop that sells the exchange. */
const pathA = (s: number) =>
  starD(
    SEAT_A.cx,
    SEAT_A.cy,
    lerp(R_BIG, R_SMALL, s),
    lerp(PULL_BIG, PULL_SMALL, s),
  );

const pathB = (s: number) =>
  starD(
    SEAT_B.cx,
    SEAT_B.cy,
    lerp(R_SMALL, R_BIG, s),
    lerp(PULL_SMALL, PULL_BIG, s),
  );

/* ── Springs (playAnimation) ─────────────────────────────────────────────── */
/** Enough bounce to read as a pop, not a wobble. */
const SWAP_SPRING = {
  type: "spring",
  visualDuration: 0.2,
  bounce: 0.3,
} as const;
/** Beat at each end before it trades back. */
const HOLD = 0.03;
/** How many out-and-back cycles one hover plays: big→small→big, once.
 *  Raising this repeats the trade; the scrub twin below is generated from the
 *  same number, so the two choreographies stay the same length either way. */
const CYCLES = 1;

/* ── Scrub twin (createScrubber) — keyframes only ────────────────────────── */
/**
 * ONE cycle, hand-drawn as the spring's shape: overshoot past the target,
 * correct, settle — out, then back. Both halves start on easeOut (the spring's
 * launch) and correct on easeInOut.
 */
const CYCLE_VALUES = [1.14, 0.95, 1.02, 1, -0.14, 0.05, -0.02, 0];
/** Where each of those lands within its own cycle, as a fraction of it. */
const CYCLE_TIMES = [0.17, 0.28, 0.37, 0.44, 0.61, 0.72, 0.83, 1];
const CYCLE_EASES: Easing[] = [
  "easeOut",
  "easeInOut",
  "easeInOut",
  "easeInOut",
  "easeOut",
  "easeInOut",
  "easeInOut",
  "easeInOut",
];

/** Matches the measured length of the real spring run (~0.83s per cycle), so
 *  the Scrub Lab's timeline is the same length as the hover gesture. */
const SCRUB_TOTAL = 0.83 * CYCLES;
/** Repeated CYCLES times, so the twin tracks however many passes the springs
 *  play without the two definitions drifting apart by hand. */
const SCRUB_KEYFRAMES = [
  0,
  ...Array.from({ length: CYCLES }, () => CYCLE_VALUES).flat(),
];
const SCRUB_TIMES = [
  0,
  ...Array.from({ length: CYCLES }, (_, c) =>
    CYCLE_TIMES.map((t) => (c + t) / CYCLES),
  ).flat(),
];
const SCRUB_EASES: Easing[] = Array.from(
  { length: CYCLES },
  () => CYCLE_EASES,
).flat();

function buildScrubSequence(swap: MotionValue<number>): AnimationSequence {
  return [
    [
      swap,
      SCRUB_KEYFRAMES,
      { duration: SCRUB_TOTAL, times: SCRUB_TIMES, ease: SCRUB_EASES },
    ],
  ];
}

export const SparkleIcon = forwardRef<
  IconHandle,
  Omit<SVGProps<SVGSVGElement>, "ref">
>((props, ref) => {
  const [scope, animate] = useAnimate();
  const shouldReduceMotion = useReducedMotion();
  const swap = useMotionValue(0);
  const aRef = useRef<SVGPathElement>(null);
  const bRef = useRef<SVGPathElement>(null);

  const aD = useTransform(swap, pathA);
  useMotionValueEvent(aD, "change", (d) => {
    aRef.current?.setAttribute("d", d);
  });

  const bD = useTransform(swap, pathB);
  useMotionValueEvent(bD, "change", (d) => {
    bRef.current?.setAttribute("d", d);
  });

  useImperativeHandle(ref, () => ({
    async playAnimation() {
      // Guarded here as well as in the trigger row: the export gallery's
      // preview hover has no reduced-motion check of its own.
      if (shouldReduceMotion) return;
      swap.jump(0);
      // Discrete awaited springs, NOT an AnimationSequence — see the
      // storyboard note. Each pass is out (A shrinks, B grows) and back
      // again; the back half is also the way home, so however many cycles
      // run, the gesture ends on the rest pose.
      for (let i = 0; i < CYCLES; i++) {
        await animate(swap, 1, i === 0 ? SWAP_SPRING : { ...SWAP_SPRING, delay: HOLD });
        await animate(swap, 0, { ...SWAP_SPRING, delay: HOLD });
      }
    },
    createScrubber() {
      swap.jump(0);
      return makeScrubber(
        () => animate(buildScrubSequence(swap)),
        // Sequence cancel restores DOM attributes, but the motion value keeps
        // its last scrubbed value; reset so both stars recompute to rest.
        () => swap.jump(0),
      );
    },
  }));

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="18"
      height="18"
      viewBox="0 0 18 18"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.5}
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{ overflow: "visible" }}
      ref={scope}
      {...props}
    >
      {/* d is driven imperatively from the single swap value. */}
      <path ref={aRef} d={pathA(0)} />
      <path ref={bRef} d={pathB(0)} />
    </svg>
  );
});

SparkleIcon.displayName = "SparkleIcon";

import type { IconScrubber } from "./types";

/**
 * Structural subset of Motion's AnimationPlaybackControls that scrubbing
 * needs; both `animate(sequence)` and `animate(value, ...)` results satisfy
 * it, so icons don't have to care which form their timeline takes.
 */
interface PlaybackControls {
  duration: number;
  time: number;
  pause(): void;
  stop(): void;
}

/**
 * Turn an icon's animation into a paused, seekable scrubber. The animation
 * is created and paused immediately (before the first frame renders), so
 * the icon holds its rest pose until the first seek.
 */
export function makeScrubber(
  createAnimation: () => PlaybackControls,
  onDestroy?: () => void
): IconScrubber {
  const controls = createAnimation();
  controls.pause();
  const duration = controls.duration;

  const nudge = () => {
    controls.time = Math.min(1e-4, duration);
    controls.time = 0;
  };

  // Repair the t=0 pose once Motion has resolved keyframes. A freshly
  // created, immediately paused sequence flushes *unresolved* fill values
  // into the DOM (e.g. the Automations pulse gets a literal
  // opacity="undefined" attribute and renders fully visible instead of
  // hidden). Resolution happens on Motion's frame loop, so wait two frames,
  // then seek away from and back to 0 to force one resolved render.
  // Skipped if the user scrubs first - a real seek renders correctly.
  let pendingInit: number | null = requestAnimationFrame(() => {
    pendingInit = requestAnimationFrame(() => {
      pendingInit = null;
      nudge();
    });
  });
  const cancelInit = () => {
    if (pendingInit !== null) {
      cancelAnimationFrame(pendingInit);
      pendingInit = null;
    }
  };

  return {
    duration,
    seek(seconds: number) {
      cancelInit();
      const t = Math.min(Math.max(seconds, 0), duration);
      // Plain `time = 0` on the never-rendered timeline replays the
      // unresolved-fill bug above; route through the nudge instead.
      if (t === 0) nudge();
      else controls.time = t;
    },
    destroy() {
      cancelInit();
      // stop(), not cancel(): cancel() on an animation that has not rendered
      // a frame yet (React StrictMode's create->destroy->create effect cycle)
      // writes unresolved "undefined" values back into the DOM, corrupting
      // the icon. stop() never writes; callers remount the icon per scrub
      // session, so rest-state restoration comes from React.
      controls.stop();
      onDestroy?.();
    },
  };
}

/**
 * A paused handle onto an icon's full animation timeline, for posing it at
 * an arbitrary moment (the Scrub Lab). Times are in seconds, matching
 * Motion's AnimationPlaybackControls.
 */
export interface IconScrubber {
  /** Total timeline length in seconds. */
  duration: number;
  /** Pose the animation at `seconds` (clamped to [0, duration]). */
  seek(seconds: number): void;
  /** Cancel the paused animation and return the icon to its rest state. */
  destroy(): void;
}

export interface IconHandle {
  playAnimation(): Promise<void>;
  /** Optional: create a paused, seekable instance of the same timeline. */
  createScrubber?(): IconScrubber;
}

"use client";

import { forwardRef, useImperativeHandle, useRef, type SVGProps } from "react";
import {
  useAnimate,
  useMotionValue,
  useMotionValueEvent,
  useReducedMotion,
  useTransform,
  type AnimationSequence,
  type Easing,
  type MotionValue,
} from "motion/react";
import { makeScrubber } from "./scrub";
import type { IconHandle } from "./types";

/* ─────────────────────────────────────────────────────────
 * ANIMATION STORYBOARD — the arrow is drawn back like a dart,
 * then thrown; its wings spin up around the shaft (hover)
 *
 *     0ms  arrow at rest, wings open, stroke 2.5
 *  0-400ms DRAW BACK — the whole arrow slides 2.5 units LEFT,
 *          decelerating into the pull. The wings have barely
 *          started turning (~44° by here): the quiet half of
 *          the wind-up.
 *   400ms  held at the back for 70ms — the beat before release
 *   470ms  THROW — the arrow snaps a full 5.5 units forward,
 *          carrying 3 units PAST its rest spot, on an expo-out;
 *          the wings WHIP through 165° → 280° in the next
 *          fifth of a second
 *   745ms  the arrow eases back to rest as the spin finishes
 *  1200ms  wings land at 360°, arrow at 0 — pixel-identical
 *          to rest (§0.2)
 *
 * ONLY THE WINGS ROTATE, and that is forced rather than
 * chosen: the axis of rotation IS the shaft. Anything lying on
 * the axis is fixed under a rotation about it, so the shaft
 * cannot turn — it only slides, and only its THICKNESS reacts.
 *
 * ── Why this reads as 3D (docs/3D-ANIMATION.md) ────────────
 * The first version of this icon only foreshortened the wings
 * (spread = 7·cosθ) and left both strokes at 2.5. That is the
 * approach the doc explicitly rejects — "foreshorten only:
 * reads flat at every angle except the crossfaded instant" —
 * and it did. Nothing ever gained volume, so it read as a
 * chevron being squashed, not an object turning.
 *
 * The fix is thickness. The arrow is a PLATE of half-thickness
 * E lying in the icon plane, turning about the shaft. Its two
 * faces sit at ±E, so under the projection they separate in y
 * by 2E·sinθ, and every stroke becomes the hull of its own two
 * offset copies — i.e. the same stroke WIDENED. Per doc §3, a
 * rod lying ALONG the axis widens exactly:
 *
 *     width(θ) = w₀·|cosθ| + 2E·|sinθ|     (2.5 → 3.5 → 2.5)
 *
 * so edge-on the shaft is a solid 3.5-unit slab, not a 2.5
 * line. That swelling is the whole depth cue — geometry only,
 * one currentColor, no shading, no crossfade (§2.4).
 *
 * The wings are the same idea on a rod that is NOT on the
 * axis and whose direction changes as it turns, so the two
 * components have to be projected separately. In-plate the
 * wing runs (-7, +7) from the tip; at angle θ it projects to
 * (-7, 7cosθ), so with L = √(1+cos²θ):
 *
 *     width(θ) = [√2·w₀·|cosθ| + 2E·|sinθ|] / L
 *
 * — the first term is the wing's own stroke foreshortening,
 * the second the extrusion. It hits w₀ exactly at rest and 2E
 * exactly edge-on, where the wings lie flat along the axis and
 * vanish flush inside the shaft's slab: an arrow seen down its
 * own plane shows no head, exactly as KeyIcon's teeth vanish
 * into its blade.
 *
 * Skipped deliberately: the hull also stretches ALONG each
 * wing by 2E·|sinθcosθ|/L. Adding it would push the wings past
 * the tip and blunt the arrowhead's point; it peaks at 0.6
 * units near 45° and the round caps already cover most of it.
 *
 * LOOP: spread = 7·cosθ, so every multiple of 180° maps the
 * chevron onto itself (the wings simply swap, and the chevron
 * is symmetric) while both widths return to w₀. 360° therefore
 * lands on the rest pose exactly — §5 strategy 3, composition
 * hand-off, no fade and no clone.
 *
 * THE SPIN EASE IS THE POINT: [0.85, 0, 0.45, 1] stays flat
 * through the whole wind-up and then whips — 2° at 10% of the
 * way, 44° at 40%, 165° at 60%, 281° at 70%. Slow, then very
 * fast, with just enough curve in the tail to land instead of
 * hard-cutting. A plain easeIn would end at maximum speed and
 * stop dead.
 *
 * TWEENS IN A SEQUENCE, NOT SPRINGS. Springs must go in
 * discrete animate() calls (see SparkleIcon); tweens declare a
 * duration, so they resolve in a sequence and stay seekable —
 * one definition serves playAnimation() and the Scrub Lab.
 * ───────────────────────────────────────────────────────── */

const n = (v: number) => Number(v.toFixed(3));

/** The shaft — which is also the axis of rotation. */
const AXIS_Y = 12;
const TAIL_X = 5;
const TIP_X = 19;
/** Where the wings' trailing ends sit, and how far off the axis. */
const WING_X = 12;
const WING_SPREAD = 7;

const STROKE = 2.5;
/**
 * Half-thickness of the plate, viewBox units — the edge-on slab is 2E = 3.5.
 * The doc's rule of thumb is 2E ≈ 3 on a 24 grid; this glyph's stroke is a
 * heavy 2.5, so 3.5 keeps KeyIcon's slab-to-stroke ratio (~1.4×) and stays
 * legible as a swelling rather than reading as a 1-unit nudge.
 */
const EXTRUDE = 1.75;

/** Two collapse-and-reopen beats. Any multiple of 180 lands on rest. */
const SPIN_DEGREES = 360;
/** Dart travel, viewBox units: back on the wind-up, past rest on the throw. */
const DRAW_BACK = 2.5;
const THROW_PAST = 3;

/**
 * The whole glyph for one (slide, angle) pair. Both paths carry a per-frame
 * stroke-width — that widening IS the depth, so it is not optional garnish.
 */
function frame(dx: number, deg: number) {
  const t = (deg * Math.PI) / 180;
  const cos = Math.cos(t);
  const sin = Math.sin(t);
  const ac = Math.abs(cos);
  const as = Math.abs(sin);
  // Projected length factor of the wing's in-plate direction (-7, 7).
  const L = Math.sqrt(1 + cos * cos);
  const spread = WING_SPREAD * cos;

  return {
    // On-axis rod: doc §3 exactly. w₀ at rest, 2E edge-on. Widths are strings
    // because they go straight to setAttribute.
    shaftWidth: (STROKE * ac + 2 * EXTRUDE * as).toFixed(3),
    shaftD: `M${n(TAIL_X + dx)} ${AXIS_Y}H${n(TIP_X + dx)}`,
    // Off-axis diagonal rod: own stroke foreshortens, extrusion adds width.
    wingWidth: ((Math.SQRT2 * STROKE * ac + 2 * EXTRUDE * as) / L).toFixed(3),
    // Both wings as one polyline through the tip. Always M L L, so every
    // scrub seek lands on valid geometry. At dx=0, θ=0 this is the supplied
    // glyph's head exactly: M12 19L19 12L12 5.
    wingsD:
      `M${n(WING_X + dx)} ${n(AXIS_Y + spread)}` +
      `L${n(TIP_X + dx)} ${AXIS_Y}` +
      `L${n(WING_X + dx)} ${n(AXIS_Y - spread)}`,
  };
}

const REST = frame(0, 0);

const DURATION = 1.2;

/** Wind up slow, whip, short landing — see the storyboard note. */
const SPIN_EASE: Easing = [0.85, 0, 0.45, 1];

/** Pull back, hold, snap forward past rest, ease home. */
const SLIDE_KEYFRAMES = [0, -DRAW_BACK, -DRAW_BACK, THROW_PAST, 0];
const SLIDE_TIMES = [0, 0.33, 0.39, 0.62, 1];
const SLIDE_EASES: Easing[] = [
  "easeOut",
  "linear",
  [0.16, 1, 0.3, 1],
  "easeInOut",
];

function buildSequence(
  spin: MotionValue<number>,
  slide: MotionValue<number>,
): AnimationSequence {
  return [
    [spin, [0, 1], { duration: DURATION, ease: SPIN_EASE }],
    [
      slide,
      SLIDE_KEYFRAMES,
      { at: 0, duration: DURATION, times: SLIDE_TIMES, ease: SLIDE_EASES },
    ],
  ];
}

export const ArrowIcon = forwardRef<
  IconHandle,
  Omit<SVGProps<SVGSVGElement>, "ref">
>((props, ref) => {
  const [scope, animate] = useAnimate();
  const shouldReduceMotion = useReducedMotion();
  const spin = useMotionValue(0);
  const slide = useMotionValue(0);
  const shaftRef = useRef<SVGPathElement>(null);
  const wingsRef = useRef<SVGPathElement>(null);

  // One computed frame feeds both paths, so the shaft and wings can never
  // disagree about the angle they are drawn at.
  const pose = useTransform(() => frame(slide.get(), spin.get() * SPIN_DEGREES));
  useMotionValueEvent(pose, "change", (f) => {
    const shaft = shaftRef.current;
    if (shaft) {
      shaft.setAttribute("d", f.shaftD);
      shaft.setAttribute("stroke-width", f.shaftWidth);
    }
    const wings = wingsRef.current;
    if (wings) {
      wings.setAttribute("d", f.wingsD);
      wings.setAttribute("stroke-width", f.wingWidth);
    }
  });

  useImperativeHandle(ref, () => ({
    async playAnimation() {
      // Guarded here as well as in the trigger row: the export gallery's
      // preview hover has no reduced-motion check of its own.
      if (shouldReduceMotion) return;
      spin.jump(0);
      slide.jump(0);
      await animate(buildSequence(spin, slide));
    },
    createScrubber() {
      spin.jump(0);
      slide.jump(0);
      return makeScrubber(
        () => animate(buildSequence(spin, slide)),
        // Sequence cancel restores DOM attributes, but the motion values keep
        // their last scrubbed value; reset so both paths recompute to rest.
        () => {
          spin.jump(0);
          slide.jump(0);
        },
      );
    },
  }));

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="24"
      height="24"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={STROKE}
      strokeLinecap="round"
      strokeLinejoin="round"
      // The dart travel runs 2.5 left and 3 right of the glyph's own box.
      style={{ overflow: "visible" }}
      ref={scope}
      {...props}
    >
      {/* d and stroke-width are both driven from the slide / spin values. */}
      <path ref={shaftRef} d={REST.shaftD} strokeWidth={REST.shaftWidth} />
      <path ref={wingsRef} d={REST.wingsD} strokeWidth={REST.wingWidth} />
    </svg>
  );
});

ArrowIcon.displayName = "ArrowIcon";

