import { makeScrubber } from "./scrub";
import type { IconHandle } from "./types";

/* ─────────────────────────────────────────────────────────
 * ANIMATION STORYBOARD — 3D heart spin around the centre
 * vertical axis
 *
 *    0ms  heart rests face-on, plain flat glyph          (0°)
 * ~100ms  the outline's barrel swells sideways; the
 *         hollow inside stays see-through                (→90°)
 * ~145ms  the cleft between the lobes pinches shut — a
 *         notch that shallow cannot survive the turn    (~74°)
 * ~159ms  the hollow closes too: you cannot see through
 *         the rim of anything this near edge-on         (~82°)
 * ~175ms  edge-on: one solid slab, 2·EXTRUDE wide        (90°)
 * ~350ms  the rear sweeps past — a heart is symmetric
 *         about this axis, so the back reads as the
 *         same heart, no mirrored glyph needed          (180°)
 * ~525ms  edge-on again                                 (270°)
 *  700ms  settles face-on, identical to rest            (360°)
 *
 * OVER ALL OF IT, A BEAT: the glyph swells to 1.14 and
 * settles back, on HomeDoorIcon's POP spring (see
 * POP_CURVE). It peaks at ~185ms, right as the heart
 * turns edge-on, so the swell reads as the impulse that
 * threw it into the spin rather than a separate wobble;
 * it undershoots to 0.98 around 478ms and is home to
 * exactly 1 by 700ms, landing with the turn.
 *
 * Uniform scale, so it cannot fight the projection: the
 * squash below is scaleX only, and a uniform swell on top
 * changes the heart's SIZE without touching how far round
 * it reads as having turned.
 *
 * Solid-silhouette technique per docs/3D-ANIMATION.md, on
 * CoinIcon's VERTICAL axis (x = CX). The heart's face is a
 * RIBBON — a closed stroke with a hollow middle — so it has
 * the same "outer outline + through-hole" structure the coin
 * rim has. What it does NOT have is a circle's closed form:
 * there is no hull-of-two-ellipses and no vesica to solve, so
 * the two contours are baked as ROW PROFILES instead (see
 * below) and the per-frame silhouette is 1D morphology on
 * them:
 *
 *   solid = outer contour DILATED  by a  (union over depth)
 *   hole  = inner contour ERODED   by a  (what both the front
 *           and the back opening let you see through)
 *
 * Per row that is just [l−a, r+a] and [l+a, r−a] — the exact
 * same rule the coin's hull/vesica pair is a special case of.
 * Both close by geometry: the cleft when the notch is
 * narrower than 2a, the hole when the ribbon's opening is.
 * No fades, no CSS 3D, no layer stacks, no crossfades.
 *
 * ONE FACE, not two. §2.2's signed cosθ mirrors the glyph
 * past 90° on its own, and a heart mirrored about its own
 * vertical axis is the same heart — so unlike the coin's $
 * there is nothing to pre-mirror and no face to gate.
 *
 * Everything derives from ONE progress value, so hover play
 * and the Scrub Lab pose the same pure function of time, and
 * rest is pixel-identical to the flat icon (§2.5).
 * ───────────────────────────────────────────────────────── */

const DURATION = 0.7;

/** Half-thickness of the heart, viewBox units. Edge-on slab = 2× this
 *  (2.2 on this 19-grid ≈ the doc's "≈3 on a 24-grid" rule). */
const EXTRUDE = 1.1;

const STROKE = 1.5;

/** The rotation axis: the heart's own vertical centre line. */
const CX = 8.8616;

const TAU = Math.PI * 2;

/**
 * The glyph, symmetrised about x = CX. The drawing as supplied sat 0.31
 * units lower on its right shoulder than its left; every mirror pair is
 * averaged here (a ≤0.16-unit move, invisible at icon sizes) so that the
 * axis is a true axis of symmetry. Everything below — the mirrored halves
 * of the silhouette, the notch closing ON the axis, the back face reading
 * as the same heart — depends on that.
 */
const HEART_D =
  "M0.8616 6.2217C1.6536 9.7854 6.4306 15.449 8.7903 17.9879" +
  "C8.8298 18.0304 8.8934 18.0304 8.9329 17.9879" +
  "C11.2926 15.449 16.0696 9.7854 16.8616 6.2217" +
  "C17.8515 1.767 11.9818 -1.8617 8.9532 3.4009" +
  "C8.9137 3.4695 8.8095 3.4695 8.77 3.4009" +
  "C5.7414 -1.8617 -0.1283 1.767 0.8616 6.2217Z";

/**
 * Row profiles of the flat glyph's two contours, right half only (the left
 * half is the mirror). Each entry is [y, distance from the axis], ordered
 * top → bottom, adaptively sampled so the chord error stays under 0.01
 * units — derived from HEART_D by scripts/heart3d-profile.mjs, which scans
 * the stroke region row by row rather than offsetting the curve (naive
 * offsetting self-intersects at the cleft and at the point).
 *
 * FLANK = the outward-facing side, apex of a lobe → the point.
 * NOTCH = the cleft's wall, apex of a lobe → where the two walls meet.
 * Above the cleft every row is two intervals; below it, one.
 */
type Profile = ReadonlyArray<readonly [number, number]>;

const OUTER_FLANK: Profile = [
  [0.047, 3.925], [0.083, 4.492], [0.12, 4.726], [0.193, 5.056], [0.339, 5.517],
  [0.486, 5.866], [0.632, 6.154], [0.924, 6.623], [1.217, 7.002], [1.51, 7.318],
  [1.802, 7.589], [2.095, 7.823], [2.387, 8.025], [2.68, 8.2], [2.972, 8.351],
  [3.557, 8.589], [4.142, 8.748], [4.728, 8.838], [5.313, 8.86], [5.898, 8.817],
  [6.483, 8.709], [7.068, 8.545], [7.653, 8.336], [8.238, 8.089], [8.823, 7.81],
  [9.408, 7.504], [10.578, 6.822], [11.749, 6.062], [12.919, 5.238],
  [14.089, 4.36], [15.259, 3.432], [16.429, 2.458], [17.6, 1.438],
  [18.185, 0.91], [18.477, 0.64], [18.623, 0.475], [18.697, 0.344],
  [18.733, 0.246], [18.77, 0],
];

const OUTER_NOTCH: Profile = [
  [0.047, 3.925], [0.08, 3.386], [0.114, 3.165], [0.18, 2.854], [0.314, 2.421],
  [0.447, 2.095], [0.581, 1.825], [0.848, 1.384], [1.115, 1.025],
  [1.381, 0.719], [1.648, 0.451], [2.182, 0],
];

const INNER_FLANK: Profile = [
  [1.547, 3.925], [1.577, 4.343], [1.607, 4.516], [1.667, 4.76], [1.788, 5.101],
  [1.908, 5.359], [2.028, 5.573], [2.269, 5.919], [2.51, 6.196], [2.751, 6.426],
  [2.991, 6.62], [3.232, 6.785], [3.473, 6.924], [3.955, 7.138], [4.436, 7.277],
  [4.918, 7.349], [5.399, 7.357], [5.881, 7.303], [6.362, 7.191],
  [6.844, 7.037], [7.325, 6.85], [7.807, 6.636], [8.288, 6.4], [9.251, 5.87],
  [10.215, 5.278], [11.178, 4.635], [12.141, 3.949], [13.104, 3.225],
  [14.067, 2.467], [15.03, 1.676], [15.993, 0.854], [16.956, 0],
];

const INNER_NOTCH: Profile = [
  [1.547, 3.925], [1.588, 3.44], [1.63, 3.241], [1.713, 2.964], [1.879, 2.58],
  [2.045, 2.293], [2.211, 2.057], [2.543, 1.675], [2.875, 1.367],
  [3.207, 1.108], [3.538, 0.884], [3.87, 0.678], [4.036, 0.508],
  [4.119, 0.369], [4.161, 0.264], [4.202, 0],
];

/** Row where the inner contour's two notch walls meet; below it the hole is
 *  a single interval and the notch stops cutting into it. */
const INNER_CLEFT_Y = INNER_NOTCH[INNER_NOTCH.length - 1][0];

/** Linear read of a profile at an arbitrary row (profiles are y-monotone). */
function profileAt(prof: Profile, y: number): number {
  if (y <= prof[0][0]) return prof[0][1];
  const last = prof[prof.length - 1];
  if (y >= last[0]) return last[1];
  let lo = 0;
  let hi = prof.length - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (prof[mid][0] <= y) lo = mid;
    else hi = mid;
  }
  const [y0, x0] = prof[lo];
  const [y1, x1] = prof[hi];
  return y1 === y0 ? x1 : x0 + ((y - y0) / (y1 - y0)) * (x1 - x0);
}

/* ── The beat ─────────────────────────────────────────────────────────────
 * HomeDoorIcon's POP, borrowed whole: spring(visualDuration 0.26, bounce 0.46)
 * driven to PEAK. There the house pops as its door swings; here the heart
 * swells as it turns away and has settled by the time it lands face-on.
 *
 * BAKED, NOT ANIMATED. Everything in this icon is a pure function of
 * `progress` — that is what lets hover play and the Scrub Lab share one
 * definition. A live spring cannot join that sequence (its duration is
 * derived, not declared), so it would need its own animate() call plus a
 * hand-synced keyframe twin for scrubbing, and those two drift — it is what
 * made BookmarkIcon's book react a beat late. So the spring is sampled off
 * Motion's own generator by scripts/heart-pop-curve.mjs and read back as a
 * table, which keeps the pop seekable for free and rest exactly 1.
 *
 * Same shape as the silhouette profiles above and read the same way, so
 * profileAt does the work — it is just a linear read of a monotone table, and
 * progress is monotone. Here the pair is [progress, scale] rather than
 * [row, distance]. Linear reads land within 0.0013 of the real spring, 0.12%
 * of scale.
 */
const POP_CURVE: Profile = [
  [0.0, 1.0], [0.0186, 1.0044], [0.04, 1.0179], [0.0614, 1.0371], [0.1243, 1.1001],
  [0.1457, 1.118], [0.1671, 1.1327], [0.19, 1.1444], [0.2129, 1.1523], [0.2371, 1.157],
  [0.2643, 1.1587], [0.3157, 1.155], [0.4243, 1.1417], [0.4371, 1.1377], [0.4514, 1.1294],
  [0.4686, 1.1154], [0.5343, 1.0486], [0.5671, 1.0201], [0.6029, 0.9981], [0.64, 0.9854],
  [0.6657, 0.9817], [0.6957, 0.9813], [0.8657, 1.0001], [1.0, 1.0],
];

/** Centre of the glyph's box in viewBox units — CX is the axis by
 *  construction, and the profiles span y 0.047 → 18.77. The swell grows from
 *  here, so it cannot drift sideways off the spin axis. */
const POP_ORIGIN = `${CX}px 9.41px`;

const pt = (x: number, y: number) => `${x.toFixed(3)} ${y.toFixed(3)}`;

/**
 * Silhouette of the extruded heart as an evenodd pair of outlines.
 *
 * Solid: the outer contour swept ±a sideways. Traced up the right flank,
 * across the lobe apex (dilating a horizontal-tangent point inserts a 2a
 * bridge — that IS the apex cap), down the cleft's right wall, across the
 * cleft, and back up the mirror. Clamping the walls at the axis is what
 * closes the cleft: they cannot cross, they meet.
 *
 * Hole: the inner contour eroded by a — per row [l+a, r−a], the overlap of
 * the front and back openings. It is bounded by the flank on the outside
 * and by the cleft wall (or the axis, below the cleft) on the inside, and
 * exists only on rows where the first still clears the second. That test
 * is what erases the lobe caps first and the point last, and finally the
 * whole hole a few degrees before edge-on — you cannot see through the
 * heart's rim when it is turned that far.
 */
function heartBodyPath(p: number): string {
  const theta = TAU * p;
  const a = Math.abs(EXTRUDE * Math.sin(theta));
  const c = Math.abs(Math.cos(theta));

  const solid: string[] = [];
  for (let i = OUTER_FLANK.length - 1; i >= 0; i--) {
    const [y, x] = OUTER_FLANK[i];
    solid.push(pt(CX + x * c + a, y));
  }
  // The cleft, dilated: each wall moves a toward the axis, and where that
  // would carry them past each other they simply meet. The row they meet on
  // is interpolated in rather than clamped at whichever profile rows happen
  // to bracket it — clamping alone leaves the notch a sliver too deep, and
  // the rear of the glyph shows through the gap.
  const wall: Array<[number, number]> = [];
  for (const [y, x] of OUTER_NOTCH) {
    const w = x * c - a;
    if (w > 0) {
      wall.push([y, w]);
      continue;
    }
    const prev = wall[wall.length - 1];
    wall.push(
      prev ? [prev[0] + (prev[1] / (prev[1] - w)) * (y - prev[0]), 0] : [y, 0],
    );
    break;
  }
  for (const [y, w] of wall) solid.push(pt(CX + w, y));
  // The row the walls meet on sits ON the axis, so it is its own mirror.
  for (let i = wall.length - 2; i >= 0; i--) {
    solid.push(pt(CX - wall[i][1], wall[i][0]));
  }
  for (const [y, x] of OUTER_FLANK) solid.push(pt(CX - (x * c + a), y));
  const d = `M${solid.join("L")}Z`;

  const holeFar = (y: number) => profileAt(INNER_FLANK, y) * c - a;
  const holeNear = (y: number) =>
    y <= INNER_CLEFT_Y ? profileAt(INNER_NOTCH, y) * c + a : 0;
  const open = (y: number) => holeFar(y) - holeNear(y) > 0;

  let first = -1;
  for (let i = 0; i < INNER_FLANK.length; i++) {
    if (open(INNER_FLANK[i][0])) {
      first = i;
      break;
    }
  }
  if (first < 0) return d; // turned far enough that nothing shows through

  let last = INNER_FLANK.length - 1;
  while (last > first && !open(INNER_FLANK[last][0])) last--;

  // Where the two bounds cross: the row the hole opens on / closes on.
  const edge = (yOpen: number, yShut: number) => {
    for (let i = 0; i < 20; i++) {
      const mid = (yOpen + yShut) / 2;
      if (open(mid)) yOpen = mid;
      else yShut = mid;
    }
    return yOpen;
  };
  const yTop =
    first === 0
      ? INNER_FLANK[0][0]
      : edge(INNER_FLANK[first][0], INNER_FLANK[first - 1][0]);
  const yBot =
    last === INNER_FLANK.length - 1
      ? INNER_FLANK[last][0]
      : edge(INNER_FLANK[last][0], INNER_FLANK[last + 1][0]);

  const hole: string[] = [pt(CX + holeFar(yTop), yTop)];
  for (let i = first; i <= last; i++) {
    const y = INNER_FLANK[i][0];
    hole.push(pt(CX + holeFar(y), y));
  }
  hole.push(pt(CX + holeFar(yBot), yBot));
  for (let i = last; i >= first; i--) {
    const y = INNER_FLANK[i][0];
    hole.push(pt(CX - holeFar(y), y));
  }
  hole.push(pt(CX - holeFar(yTop), yTop));
  if (yTop < INNER_CLEFT_Y - 1e-6) {
    // The cleft still bites into the hole: down one wall, across, up the other.
    const walls = INNER_NOTCH.filter(([y]) => y > yTop);
    for (const [y] of walls) hole.push(pt(CX - holeNear(y), y));
    for (let i = walls.length - 1; i >= 0; i--) {
      const y = walls[i][0];
      hole.push(pt(CX + holeNear(y), y));
    }
  }
  return `${d} M${hole.join("L")}Z`;
}

function buildSequence(progress: MotionValue<number>): AnimationSequence {
  return [[progress, [0, 1], { duration: DURATION, ease: "easeInOut" }]];
}

export const HeartIcon = forwardRef<
  IconHandle,
  Omit<SVGProps<SVGSVGElement>, "ref">
>((props, ref) => {
  const [scope, animate] = useAnimate();
  const shouldReduceMotion = useReducedMotion();
  const progress = useMotionValue(0);
  const bodyRef = useRef<SVGPathElement>(null);

  // Front face: squash by cosθ toward the axis, slide +EXTRUDE·sinθ along its
  // perpendicular (the x-axis — the axis is vertical, so no rotate sandwich).
  // translateX sits left of scaleX so the slide is not itself squashed. The
  // fill-box centre is x = CX by construction (the glyph is symmetrised about
  // the axis), so the squash cannot drift sideways.
  const frontTransform = useTransform(progress, (p) => {
    const theta = TAU * p;
    const slide = (EXTRUDE * Math.sin(theta)).toFixed(4);
    const squash = Math.cos(theta).toFixed(4);
    return `translateX(${slide}px) scaleX(${squash})`;
  });

  // The beat, read straight off the baked spring — same progress, so it can
  // never fall out of step with the turn.
  const popScale = useTransform(progress, (p) => profileAt(POP_CURVE, p));

  const bodyD = useTransform(progress, heartBodyPath);
  useMotionValueEvent(bodyD, "change", (v) => {
    bodyRef.current?.setAttribute("d", v);
  });

  useImperativeHandle(ref, () => ({
    async playAnimation() {
      // Guarded here as well as in the trigger row: the export gallery's
      // preview hover has no reduced-motion check of its own.
      if (shouldReduceMotion) return;
      progress.jump(0);
      await animate(buildSequence(progress));
    },
    createScrubber() {
      progress.jump(0);
      return makeScrubber(
        () => animate(buildSequence(progress)),
        () => progress.jump(0),
      );
    },
  }));

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="18"
      height="19"
      viewBox="0 0 18 19"
      fill="none"
      stroke="currentColor"
      strokeWidth={STROKE}
      strokeLinecap="round"
      strokeLinejoin="round"
      // The barrel swells a hair past the box at its widest turn.
      style={{ overflow: "visible" }}
      ref={scope}
      {...props}
    >
      {/* The beat. Body and face swell together, so the pop scales the whole
          turning heart rather than sliding the face off its own silhouette.
          transformOrigin lives in `initial` because Motion overrides a
          style-set origin on SVG with its centred default, and view-box units
          keep it on the spin axis — same wiring as HomeDoorIcon's pop. */}
      <motion.g
        initial={{ transformOrigin: POP_ORIGIN }}
        style={{ scale: popScale, transformBox: "view-box" }}
      >
        {/* Extruded body: the outline's silhouette with a real see-through
            hole. Solid currentColor — never shaded. At rest it coincides with
            the glyph's own stroke footprint and hides under it. */}
        <path
          ref={bodyRef}
          d={heartBodyPath(0)}
          fill="currentColor"
          fillRule="evenodd"
          stroke="none"
        />
        {/* Front face — the flat glyph itself, riding the projection. */}
        <motion.path
          d={HEART_D}
          style={{
            transform: frontTransform,
            transformOrigin: "50% 50%",
            transformBox: "fill-box",
          }}
        />
      </motion.g>
    </svg>
  );
});

HeartIcon.displayName = "HeartIcon";

"use client";

import { forwardRef, useImperativeHandle, type SVGProps } from "react";
import {
  motion,
  useAnimate,
  useReducedMotion,
  type AnimationSequence,
  type Easing,
} from "motion/react";
import { makeScrubber } from "./scrub";
import type { IconHandle } from "./types";

/* ─────────────────────────────────────────────────────────
 * ANIMATION STORYBOARD — the lid flips open, the bin shakes
 * out its contents, the lid drops shut (hover)
 *
 *      0ms  rest: closed bin, lid level
 *  0-160ms  OPEN — the lid (rail + handle) tips up 22° about
 *           its LEFT hinge on an easeOut. Fast, so the shake
 *           gets the stage.
 *  160-560ms HOLD OPEN while the CAN does a two-beat shimmy:
 *           +3.4°, -2.4°, +1° about the base centre, ~7Hz —
 *           a bin being shaken out, not a pendulum swinging.
 *           The two inner tick-lines ride the can, so the
 *           "contents" shake with it.
 *  560-680ms SNAP SHUT — the lid slams back to level in 120ms
 *           on LockIcon's bite curve [0.23, 1, 0.32, 1]: near
 *           all the travel in the first frames, then it just
 *           lands. Twice as slow going up as coming down, so
 *           the eye reads the shut as the event.
 *  680-900ms settled, closed — pixel-identical to rest (§0.2).
 *
 * TWO PARTS, TWO CLOCKS. The lid and the can are separate
 * groups on their own `times` (LockIcon / TicketIcon pattern):
 * the can must stay still until the lid is clear, shimmy only
 * while it is open, and be still again before it shuts — a
 * shared clock would smear the shake across the open and close.
 * The shake segment is fired at `at: 0.18` and ends at 0.56,
 * inside the lid's open-and-hold window (0.16 → 0.56).
 *
 * THE LID HINGES AT ITS LEFT END (4, 6), so the free right end
 * and the handle swing up and the bin mouth is uncovered — a
 * pedal-bin lid, not a sliding lift. The CAN turns about its
 * base centre (12, 22): a shimmy pivots at the feet, so the
 * mouth swings and the base stays planted.
 *
 * Class A per ICON-SYSTEM §2 — rotation only, both parts.
 * Rotation is isometric, so strokeWidth never changes and the
 * two halves keep the same weight as every other icon.
 * ───────────────────────────────────────────────────────── */

/** Lid = the rail across the top plus the handle tab above it. Rotates as
 *  one group about the hinge. */
const LID_RAIL_D = "M4 6H20";
const LID_HANDLE_D = "M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2";
/** Can = the bucket body plus the two inner tick-lines (the "contents"). */
const CAN_BODY_D = "M18 6v14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2V6";
const CAN_TICK_L_D = "M10 11v6";
const CAN_TICK_R_D = "M14 11v6";

/** Lid hinge: the rail's LEFT end, so the right end and handle lift clear. */
const LID_PIVOT = "4px 6px";
/** Can pivot: the base centre, so the shimmy swings the mouth, feet planted. */
const CAN_PIVOT = "12px 22px";

/** How far the lid tips open. */
const OPEN_DEG = 22;

const DURATION = 0.9;

/** Open fast, hold, SNAP shut, stay closed. */
const LID_ROTATE = [0, -OPEN_DEG, -OPEN_DEG, 0, 0];
const LID_TIMES = [0, 0.18, 0.62, 0.76, 1];
/** LockIcon's clipper bite for the shut — near-instant attack, soft arrival. */
const SNAP: Easing = [0.23, 1, 0.32, 1];
const LID_EASE: Easing[] = ["easeOut", "linear", SNAP, "linear"];

/** Two-beat shimmy, decaying, on the can's own clock (see storyboard). */
const SHAKE_AT = 0.18;
const SHAKE_DUR = 0.4;
const SHAKE_ROTATE = [0, 3.4, -2.4, 1, 0];
const SHAKE_TIMES = [0, 0.28, 0.56, 0.8, 1];
const SHAKE_EASE: Easing[] = ["easeInOut", "easeInOut", "easeInOut", "easeInOut"];

const SEQUENCE: AnimationSequence = [
  [
    ".trash-lid",
    { rotate: LID_ROTATE },
    { duration: DURATION, times: LID_TIMES, ease: LID_EASE },
  ],
  [
    ".trash-can",
    { rotate: SHAKE_ROTATE },
    { at: SHAKE_AT, duration: SHAKE_DUR, times: SHAKE_TIMES, ease: SHAKE_EASE },
  ],
];

export const TrashIcon = forwardRef<
  IconHandle,
  Omit<SVGProps<SVGSVGElement>, "ref">
>((props, ref) => {
  const [scope, animate] = useAnimate();
  const shouldReduceMotion = useReducedMotion();

  useImperativeHandle(ref, () => ({
    async playAnimation() {
      // Guarded here as well as in the trigger row: the export gallery's
      // preview hover has no reduced-motion check of its own.
      if (shouldReduceMotion) return;
      await animate(SEQUENCE);
    },
    createScrubber() {
      return makeScrubber(() => animate(SEQUENCE));
    },
  }));

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="24"
      height="24"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      // The lid swings above the box and the shimmy leans past its sides.
      style={{ overflow: "visible" }}
      ref={scope}
      {...props}
    >
      {/* The can shimmies about its base; ticks ride inside it. transformOrigin
          lives in `initial` (Motion overrides a style origin with its 50%/50%
          SVG default), transformBox in `style` to make the pixels view-box
          units. Rest rotate is in `initial` so the scrubber's pre-paint pause
          holds the bin still until the first seek. */}
      <motion.g
        className="trash-can"
        initial={{ rotate: 0, transformOrigin: CAN_PIVOT }}
        style={{ transformBox: "view-box" }}
      >
        <path d={CAN_BODY_D} />
        <path d={CAN_TICK_L_D} />
        <path d={CAN_TICK_R_D} />
      </motion.g>
      {/* The lid tips open and slams shut about its left hinge. */}
      <motion.g
        className="trash-lid"
        initial={{ rotate: 0, transformOrigin: LID_PIVOT }}
        style={{ transformBox: "view-box" }}
      >
        <path d={LID_RAIL_D} />
        <path d={LID_HANDLE_D} />
      </motion.g>
    </svg>
  );
});

TrashIcon.displayName = "TrashIcon";

import type { IconScrubber } from "./types";

/**
 * Structural subset of Motion's AnimationPlaybackControls that scrubbing
 * needs; both `animate(sequence)` and `animate(value, ...)` results satisfy
 * it, so icons don't have to care which form their timeline takes.
 */
interface PlaybackControls {
  duration: number;
  time: number;
  pause(): void;
  stop(): void;
}

/**
 * Turn an icon's animation into a paused, seekable scrubber. The animation
 * is created and paused immediately (before the first frame renders), so
 * the icon holds its rest pose until the first seek.
 */
export function makeScrubber(
  createAnimation: () => PlaybackControls,
  onDestroy?: () => void
): IconScrubber {
  const controls = createAnimation();
  controls.pause();
  const duration = controls.duration;

  const nudge = () => {
    controls.time = Math.min(1e-4, duration);
    controls.time = 0;
  };

  // Repair the t=0 pose once Motion has resolved keyframes. A freshly
  // created, immediately paused sequence flushes *unresolved* fill values
  // into the DOM (e.g. the Automations pulse gets a literal
  // opacity="undefined" attribute and renders fully visible instead of
  // hidden). Resolution happens on Motion's frame loop, so wait two frames,
  // then seek away from and back to 0 to force one resolved render.
  // Skipped if the user scrubs first - a real seek renders correctly.
  let pendingInit: number | null = requestAnimationFrame(() => {
    pendingInit = requestAnimationFrame(() => {
      pendingInit = null;
      nudge();
    });
  });
  const cancelInit = () => {
    if (pendingInit !== null) {
      cancelAnimationFrame(pendingInit);
      pendingInit = null;
    }
  };

  return {
    duration,
    seek(seconds: number) {
      cancelInit();
      const t = Math.min(Math.max(seconds, 0), duration);
      // Plain `time = 0` on the never-rendered timeline replays the
      // unresolved-fill bug above; route through the nudge instead.
      if (t === 0) nudge();
      else controls.time = t;
    },
    destroy() {
      cancelInit();
      // stop(), not cancel(): cancel() on an animation that has not rendered
      // a frame yet (React StrictMode's create->destroy->create effect cycle)
      // writes unresolved "undefined" values back into the DOM, corrupting
      // the icon. stop() never writes; callers remount the icon per scrub
      // session, so rest-state restoration comes from React.
      controls.stop();
      onDestroy?.();
    },
  };
}

/**
 * A paused handle onto an icon's full animation timeline, for posing it at
 * an arbitrary moment (the Scrub Lab). Times are in seconds, matching
 * Motion's AnimationPlaybackControls.
 */
export interface IconScrubber {
  /** Total timeline length in seconds. */
  duration: number;
  /** Pose the animation at `seconds` (clamped to [0, duration]). */
  seek(seconds: number): void;
  /** Cancel the paused animation and return the icon to its rest state. */
  destroy(): void;
}

export interface IconHandle {
  playAnimation(): Promise<void>;
  /** Optional: create a paused, seekable instance of the same timeline. */
  createScrubber?(): IconScrubber;
}

"use client";

import { forwardRef, useId, useImperativeHandle, type SVGProps } from "react";
import {
  motion,
  useAnimate,
  useMotionValue,
  useReducedMotion,
  useTransform,
  type MotionValue,
} from "motion/react";
import { makeScrubber } from "./scrub";
import type { IconHandle } from "./types";

/* ─────────────────────────────────────────────────────────
 * ANIMATION STORYBOARD — the plane is drawn back like a dart,
 * thrown out of the frame, and comes round again (hover)
 *
 * The wind-up is ArrowIcon's dart, on a diagonal: same 299ms
 * easeOut draw-back, same held beat, same deliberate slow half
 * before anything fast happens. What follows is not the
 * arrow's — a dart stops 3 units past rest, this leaves.
 *
 *     0ms  plane at rest
 *  0-299ms DRAW BACK — it slides 2.2 units DOWN-LEFT along its
 *          own flight line, decelerating into the pull, and
 *          tips its nose up 9° as it gathers.
 *   299ms  HELD at the back for 58ms — the beat before release.
 *          Without it the throw reads as a twitch; the pause is
 *          what makes it read as a throw.
 * 357-525ms THROW. The hand accelerates it for the first 27ms and
 *          then LETS GO: from there the speed is constant, which
 *          is the difference between a throw and a rocket. It
 *          noses over 5° and has crossed the frame edge by
 *          497ms — well before the phase ends, which is what
 *          buys the empty beat; see FLIGHT_OUT.
 *          The arrow's expo-out is deliberately NOT reused here.
 *          That curve decelerates INTO its target, which is
 *          right for a dart landing 3 units past rest and wrong
 *          for something meant to leave and keep going.
 * 497-648ms EMPTY FRAME. Nothing on screen for 151ms, and that
 *          beat is load-bearing: without it the plane re-enters
 *          the same frame it left and the whole thing reads as a
 *          teleport glitch rather than as something flying away
 *          and coming back round.
 * 525-604ms OFF-FRAME, LEVELLING. The nose comes back down from
 *          5° to 0 here, out of sight. This beat exists so that
 *          straightening up never happens in front of the
 *          viewer — see flightTilt.
 *   604ms  WRAP — offset flips +34 → −34 in one frame. Both ends
 *          sit 5-6 units clear of the clip, so the jump cannot
 *          be seen; see FLIGHT_OUT.
 * 604-1050ms RETURN, flown entirely at rest attitude. It enters
 *          from the BOTTOM-LEFT, fast, and bleeds speed to drag
 *          all the way home. It only becomes visible at 648ms,
 *          44ms after it finished levelling, so the sole pose
 *          the frame ever shows on the way back is the resting
 *          one and all there is to watch is distance closing.
 *          Ends pixel-identical to 0ms — exactly, not
 *          approximately — so replays and scrub wraps are
 *          invisible (§0.2).
 *
 * NOTHING SCALES. The plane is the same size in every frame of
 * the gesture; it only ever translates and rotates.
 *
 * THE BOX IS A REAL EDGE HERE, and it is a clipPath rather
 * than overflow:hidden. The gesture needs the plane to
 * genuinely vanish past the top-right, stay gone, and reappear
 * at the bottom-left — nothing clips it otherwise, since
 * neither .stage nor the sidebar row sets overflow, so an
 * unclipped plane would sail out across the page and then be
 * seen snapping back. Clipping the flight group instead of the
 * <svg> keeps overflow:visible on the root, as §1 wants, and
 * keeps the clip travelling with the icon wherever it is
 * exported to rather than depending on a style on the root.
 *
 * ONE AXIS. Back, throw and return all run along the plane's
 * own crease — tail (5.54, 9.23) to nose (16.99, 0.95) — so
 * the whole gesture is a single scalar offset projected onto
 * that unit vector. The plane always travels the way it points,
 * which is the only reason a 34-unit throw still reads as one
 * object rather than a shape sliding across a tile. It is also
 * why the return arrives from the bottom-left without anything
 * having to aim it there: −34 along an axis pointing up-right
 * IS the bottom-left corner.
 *
 * Everything derives from ONE progress value through pure
 * functions, which is also what makes the wrap possible: a
 * keyframed +34 → −34 would TWEEN, flashing the plane back
 * across the frame. A sampled function just steps. It also
 * keeps the Scrub Lab seeking a fixed, reproducible timeline.
 * ───────────────────────────────────────────────────────── */

const DURATION = 1.05;

/** Flight axis: the plane's own crease, tail → nose, normalised. */
const CREASE = { x: 16.9912 - 5.53662, y: 0.953213 - 9.22908 };
const CREASE_LEN = Math.hypot(CREASE.x, CREASE.y);
const UX = CREASE.x / CREASE_LEN;
const UY = CREASE.y / CREASE_LEN;

/** Phase boundaries, as fractions of DURATION. */
const P_BACK = 0.285; // wind-up ends
const P_HOLD = 0.34; // held beat ends, throw begins
const P_GONE = 0.5; // throw ends; the plane left the frame a while back
const P_AWAY = 0.575; // off-frame beat ends — the wrap happens HERE

/**
 * How far back it gathers, in viewBox units along the flight axis.
 * ArrowIcon draws back 2.5 on a 24 grid; this is the same gesture scaled to a
 * 19-wide box.
 */
const PULL = -2.2;

/**
 * How much bigger than the viewBox the clip is, per side.
 *
 * It cannot be zero. The glyph is inscribed edge to edge — its ink stops
 * 0.001 units inside the box on the left and top — so a clip on the viewBox
 * itself shaves the tail off during the wind-up, before the plane has gone
 * anywhere. The pull is 2.2 units along an axis that is 0.81 horizontal and
 * the 9° nose-up swings the tail further left still, so at full cock the tail
 * tip sits about 2.1 units outside the box. Three units of breathing room
 * clears it with most of a unit spare.
 *
 * The cost is that the plane winks out a shade outside the tile rather than
 * exactly on its border. At icon sizes that is a fraction of a pixel; being
 * clipped mid-wind-up would not be.
 */
const CLIP_PAD = 3;

/**
 * How far out the throw carries — and, mirrored, how far out the return
 * starts. One number for both, so the wrap is a pure sign flip and the two
 * sides of it are the same distance out.
 *
 * The plane's ink spans x ∈ [0.0, 18.07] and the clip runs to x = 22, so
 * clearing the right edge takes about 28 units at full size. 34 leaves the
 * plane 5.4 units clear of the right edge and 6.4 clear of the left at the
 * moment of the jump, which is what makes the wrap unseeable.
 *
 * It has to overshoot the exit distance by a good margin, not just meet it.
 * The throw runs at constant speed, so the plane crosses the frame edge at a
 * FIXED fraction of the throw phase no matter how long that phase is —
 * lengthening the phase does not buy an empty-frame beat, only a longer
 * throw does.
 *
 * THE PLANE NEVER CHANGES SIZE. An earlier version scaled it by distance,
 * on the theory that something flying away should recede; at icon size that
 * does not read as depth, it reads as the icon growing on its way back in.
 * Translation and rotation only.
 */
const FLIGHT_OUT = 34;

/** Nose attitude, in degrees. Negative is nose-up (SVG y points down). */
const TILT_BACK = -9;
/** Where the nose ends up through the throw, before it levels off-frame. */
const TILT_THROW = 5;

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const easeOutCubic = (t: number) => 1 - (1 - t) ** 3;

/**
 * cubic-bezier(x1,y1,x2,y2) as a plain value-of-time function — the same
 * parameterization as CSS and Motion's array easing, so a curve can be lifted
 * straight out of another icon. X is monotonic for any valid easing, so
 * bisecting on it to recover the curve parameter is safe.
 *
 * These have to be functions rather than an `ease` option because the whole
 * gesture is sampled from one progress value; see the storyboard.
 */
const cubicBezier = (x1: number, y1: number, x2: number, y2: number) => {
  const bez = (s: number, c1: number, c2: number) =>
    3 * (1 - s) ** 2 * s * c1 + 3 * (1 - s) * s * s * c2 + s ** 3;
  return (t: number) => {
    if (t <= 0) return 0;
    if (t >= 1) return 1;
    let lo = 0;
    let hi = 1;
    for (let i = 0; i < 24; i++) {
      const mid = (lo + hi) / 2;
      if (bez(mid, x1, x2) < t) lo = mid;
      else hi = mid;
    }
    return bez((lo + hi) / 2, y1, y2);
  };
};

/** Motion's "easeOut", which is what ArrowIcon pulls back on. */
const easeBack = cubicBezier(0, 0, 0.58, 1);

/**
 * The release. Velocity ramps from nothing to full over the first
 * THROW_ACCEL of the phase — the arm extending — and is then CONSTANT, which
 * is what "let go" means. Integrating that gives position; the result is
 * normalised so it still lands on 1.
 *
 * Starting from rest matters: the plane has been sitting still at the back of
 * the wind-up, so any curve with speed at t=0 reads as a cut rather than a
 * throw. Ending at full speed matters just as much — it leaves the frame
 * still travelling away from the hand, not settling.
 */
const THROW_ACCEL = 0.16;
const throwRelease = (() => {
  const raw = (t: number) =>
    t <= THROW_ACCEL
      ? t ** 3 / (3 * THROW_ACCEL * THROW_ACCEL)
      : THROW_ACCEL / 3 + (t - THROW_ACCEL);
  const atOne = raw(1);
  return (u: number) => raw(u) / atOne;
})();

/**
 * The arrival: viscous drag, i.e. speed decaying exponentially with time.
 * It comes in fast, bleeds off, and settles — no overshoot, because a paper
 * plane does not arrive past its target and get pulled back.
 *
 * DRAG is the decay rate. 2.4 gives an entry speed about 2.6× the average and
 * still spends the last tenth of the distance on a visible settle, without
 * the long crawl a heavier decay leaves behind. Normalised by its own value
 * at u = 1 so it lands on EXACTLY 1 — rest identity has to be exact, and a
 * curve that merely converges would leave the plane a hundredth of a unit
 * short of home forever.
 */
const DRAG = 2.4;
const glideIn = (() => {
  const atOne = 1 - Math.exp(-DRAG);
  return (u: number) => (1 - Math.exp(-DRAG * u)) / atOne;
})();

/** Progress within a phase, 0→1. */
const span = (p: number, from: number, to: number) => (p - from) / (to - from);

/**
 * Distance along the flight axis at progress `p`.
 *
 * The discontinuity at P_AWAY is the point of the whole thing — it is where
 * the plane teleports from beyond the top-right corner to beyond the
 * bottom-left one. Sampling a function rather than tweening keyframes is what
 * makes that legal: nothing interpolates across the gap, so the plane never
 * appears mid-frame during the swap.
 */
function flightOffset(p: number): number {
  if (p < P_BACK) return lerp(0, PULL, easeBack(span(p, 0, P_BACK)));
  if (p < P_HOLD) return PULL;
  if (p < P_GONE) {
    return lerp(PULL, FLIGHT_OUT, throwRelease(span(p, P_HOLD, P_GONE)));
  }
  // Out of sight and holding, at exactly the distance it comes back from.
  if (p < P_AWAY) return FLIGHT_OUT;
  return lerp(-FLIGHT_OUT, 0, glideIn(span(p, P_AWAY, 1)));
}

/**
 * Nose attitude. Tips up into the pull on the same curve the body rides,
 * noses over as it is flung, and then LEVELS OFF DURING THE OFF-FRAME BEAT.
 *
 * That placement is the point: straightening up is the one part of the
 * gesture that would look like the plane fixing itself in front of you, so it
 * happens in the phase that exists precisely because nothing is on screen.
 * The whole return is flown at rest attitude — by the time the clip lets the
 * plane be seen again it is already square, and only has distance left to
 * close.
 */
function flightTilt(p: number): number {
  if (p < P_BACK) return lerp(0, TILT_BACK, easeBack(span(p, 0, P_BACK)));
  if (p < P_HOLD) return TILT_BACK;
  if (p < P_GONE) {
    return lerp(TILT_BACK, TILT_THROW, throwRelease(span(p, P_HOLD, P_GONE)));
  }
  if (p < P_AWAY) {
    return lerp(TILT_THROW, 0, easeOutCubic(span(p, P_GONE, P_AWAY)));
  }
  return 0;
}

/** The glyph, exactly as supplied: body outline, tail fin, crease. */
const PLANE_D =
  "M10.0366 12.4015L5.53662 9.22908L1.16304 8.42474" +
  "C0.676297 8.33522 0.597387 7.67043 1.05218 7.47527" +
  "C4.1268 6.1559 11.2603 3.09476 16.6243 0.792984" +
  "C17.0021 0.630858 17.4006 0.968273 17.3021 1.36743" +
  "C16.0661 6.37687 14.3203 12.2874 13.7359 14.2395" +
  "C13.6378 14.5671 13.2484 14.6956 12.9701 14.4969L10.0366 12.4015Z" +
  "M5.53662 9.22908V15.2881C5.53662 15.7195 6.04635 15.9484 6.3688 15.6618" +
  "L10.0366 12.4015" +
  "M5.53662 9.22908C5.53662 9.22908 12.3003 4.40399 16.9912 0.953213";

export const PaperPlaneIcon = forwardRef<
  IconHandle,
  Omit<SVGProps<SVGSVGElement>, "ref">
>((props, ref) => {
  const [scope, animate] = useAnimate();
  const shouldReduceMotion = useReducedMotion();
  const progress = useMotionValue(0);
  // useId can contain colons, which are not safe inside url(#…) — strip them.
  const clipId = `paper-plane-clip-${useId().replace(/:/g, "")}`;

  const offset = useTransform(progress, flightOffset);
  const x = useTransform(offset, (d) => d * UX);
  const y = useTransform(offset, (d) => d * UY);
  const rotate = useTransform(progress, flightTilt);

  const play = (p: MotionValue<number>) => {
    p.jump(0);
    // Linear: every curve lives in the pure functions above, so easing the
    // tween as well would double-apply it.
    return animate(p, 1, { duration: DURATION, ease: "linear" });
  };

  useImperativeHandle(ref, () => ({
    async playAnimation() {
      // Guarded here as well as in the trigger row: the export gallery's
      // preview hover has no reduced-motion check of its own.
      if (shouldReduceMotion) return;
      await play(progress);
    },
    createScrubber() {
      return makeScrubber(
        () => play(progress),
        () => progress.jump(0),
      );
    },
  }));

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="19"
      height="17"
      viewBox="0 0 19 17"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.5}
      strokeLinecap="round"
      style={{ overflow: "visible" }}
      ref={scope}
      {...props}
    >
      {/* The frame edge, as geometry rather than a style on the root — see the
          storyboard, and CLIP_PAD for why it is not simply the viewBox. */}
      <defs>
        <clipPath id={clipId}>
          <rect
            x={-CLIP_PAD}
            y={-CLIP_PAD}
            width={19 + CLIP_PAD * 2}
            height={17 + CLIP_PAD * 2}
          />
        </clipPath>
      </defs>
      <g clipPath={`url(#${clipId})`}>
        <motion.g style={{ x, y, rotate }}>
          <path d={PLANE_D} />
        </motion.g>
      </g>
    </svg>
  );
});

PaperPlaneIcon.displayName = "PaperPlaneIcon";

